  // ---------------------------
  // MAIN UI
  // ---------------------------

  return (
    <div className="p-8 text-slate-100 admin-users-layout">
      <div className="admin-users-header">
        <div className="admin-users-header-left">
          <h1 className="admin-users-title">Users</h1>
          <p className="admin-users-subtitle">
