        </div>
      )}
    </div>
  );
}

import { NextResponse } from "next/server";
import { cookies } from "next/headers";
import { createServerClient } from "@supabase/ssr";

export async function POST(req: Request) {
  const cookieStore = await cookies();

  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        get(name: string) {
          return cookieStore.get(name)?.value;
        },
        set() {},
        remove() {},
      },
    }
  );

  const {
    data: { user },
  } = await supabase.auth.getUser();

  if (!user) {
    return NextResponse.json({ error: "Not authenticated" }, { status: 401 });
  }

  const res = await fetch(
    `${process.env.NEXT_PUBLIC_SUPABASE_URL}/functions/v1/create-checkout`,
    {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ user_id: user.id }),
    }
  );

  const data = await res.json();
  return NextResponse.json(data);
}

"use client";

import { useState } from "react";
import Link from "next/link";
import { supabase } from "@/lib/supabase/client"; // ✅ correct

export default function LoginPage() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");

  async function handleLogin(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setLoading(true);
    setErrorMsg("");

    const { data, error } = await supabase.auth.signInWithPassword({
      email,
      password,
    });

    if (error) {
      setErrorMsg(error.message);
      setLoading(false);
      return;
    }

    // Staff accounts get their round rather than the planning app, which they
    // have no access to anyway. owner_user_id being set is what marks one.
    let destination = "/";
    if (data.user) {
      const { data: profile } = await supabase
        .from("profiles")
        .select("owner_user_id")
        .eq("user_id", data.user.id)
        .maybeSingle();

      if (profile?.owner_user_id) destination = "/my-round";
    }

    // Give Supabase time to write the cookie
    setTimeout(() => {
      window.location.href = destination;
    }, 200);
  }

  return (
    <div className="min-h-screen bg-slate-950 flex items-center justify-center px-4">
      <div className="w-full max-w-md bg-slate-900 border border-slate-800 rounded-xl p-8 shadow-xl">
        <h1 className="text-2xl font-semibold text-slate-50 text-center">
          Log in to GeoRoutes
        </h1>
        <p className="mt-2 text-sm text-slate-400 text-center">
          Access your routes, staff schedules, and planning dashboard.
        </p>

        <form onSubmit={handleLogin} className="mt-8 space-y-5">
          <div className="space-y-1">
            <label className="text-sm text-slate-300">Email</label>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              className="w-full rounded-md border border-slate-700 bg-slate-800 px-3 py-2 text-sm text-slate-50 outline-none focus:border-teal-400"
            />
          </div>

          <div className="space-y-1">
            <label className="text-sm text-slate-300">Password</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              className="w-full rounded-md border border-slate-700 bg-slate-800 px-3 py-2 text-sm text-slate-50 outline-none focus:border-teal-400"
            />
          </div>

          {errorMsg && (
            <p className="text-red-400 text-sm">{errorMsg}</p>
          )}

          <button
            type="submit"
            disabled={loading}
            className="w-full rounded-full bg-gradient-to-r from-green-500 via-teal-500 to-teal-400 px-4 py-2 text-sm font-medium text-slate-950 hover:brightness-110 transition disabled:opacity-50"
          >
            {loading ? "Logging in..." : "Log in"}
          </button>
        </form>

        <p className="mt-6 text-xs text-slate-400 text-center">
          Don’t have an account?{" "}
          <Link href="/signup" className="text-teal-300 hover:text-teal-200">
            Create one
          </Link>
        </p>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import PricingDetail from "@/components/pricing/PricingDetail";
import Link from "next/link";
import { supabase } from "@/lib/supabase/client";
import type { User } from "@supabase/supabase-js";
import type { AnyBlock, PricingHeaderData } from "@/lib/types/cms";

const DEFAULT_HEADER: PricingHeaderData = {
  title: "Simple pricing for growing teams",
  subtitle: "Start free, then upgrade when you're ready to scale.",
};

/** A row from the pricing table, as this page renders it. */
interface PricingPlan {
  id: string;
  plan: string;
  description: string | null;
  price: number;
  features: string[] | null;
}

export default function PricingPage() {
  // Only presence is checked, never a field, so the session's own type is
  // more than this page needs.
  const [user, setUser] = useState<User | null>(null);
  const [profile, setProfile] = useState<{ is_admin: boolean } | null>(null);
  const [plans, setPlans] = useState<PricingPlan[]>([]);
  const [header, setHeader] = useState<PricingHeaderData>(DEFAULT_HEADER);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function load() {
      const [{ data: userData }, { data: pricingData }, { data: cmsData }] =
        await Promise.all([
          supabase.auth.getUser(),
          supabase.from("pricing").select("*").order("price"),
          supabase
            .from("page_content")
            .select("blocks")
            .eq("page_id", "pricing")
            .maybeSingle(),
        ]);

      const currentUser = userData?.user ?? null;
      setUser(currentUser);

      if (currentUser) {
        const { data: profileData } = await supabase
          .from("profiles")
          .select("is_pro, is_admin")
          .eq("user_id", currentUser.id)
          .maybeSingle();
        setProfile(profileData);
      }

      setPlans(pricingData ?? []);

      const headerBlock = (cmsData?.blocks as AnyBlock[] | null)?.find(
        (b) => b.type === "pricing_header"
      );
      if (headerBlock) {
        setHeader(headerBlock.data as PricingHeaderData);
      }

      setLoading(false);
    }

    load();
  }, []);

  return (
    <div className="bg-slate-950 min-h-screen">
      <div className="mx-auto max-w-6xl px-4 py-16">
        <div className="mb-10 text-center">
          <h1 className="text-3xl font-semibold tracking-tight text-slate-50 sm:text-4xl">
            {header.title}
          </h1>
          {header.subtitle && (
            <p className="mt-3 text-sm text-slate-300 sm:text-base">
              {header.subtitle}
            </p>
          )}
        </div>

        {/* Only the cards depend on fetched data. Everything else renders
            server-side so the page is never blank to a crawler or on first
            paint. */}
        <div className="grid gap-6 md:grid-cols-2">
          {(loading ? [] : plans).map((plan) => (
            <div
              key={plan.id}
              className={`rounded-2xl p-6 ${
                plan.plan === "pro"
                  ? "border border-teal-500/60 bg-gradient-to-br from-green-600 via-teal-600 to-teal-500 text-slate-950 shadow-xl shadow-teal-500/40"
                  : "border border-slate-800 bg-slate-900/80 text-slate-50"
              }`}
            >
              <h2 className="text-sm font-semibold capitalize">{plan.plan}</h2>
              <p className="mt-1 text-xs opacity-80">{plan.description}</p>

              <div className="mt-4 flex items-baseline gap-1">
                <span className="text-3xl font-semibold">£{plan.price}</span>
                <span className="text-xs opacity-80">/month</span>
              </div>

              <ul className="mt-4 space-y-2 text-xs opacity-90">
                {plan.features?.map((f: string, i: number) => (
                  <li key={i}>• {f}</li>
                ))}
              </ul>

              <Link
                href="/signup"
                className={`mt-6 inline-flex w-full items-center justify-center rounded-full px-4 py-2 text-sm font-medium transition ${
                  plan.plan === "pro"
                    ? "bg-slate-950 text-slate-50 hover:bg-slate-900"
                    : "border border-slate-700 text-slate-100 hover:bg-slate-800"
                }`}
              >
                {plan.plan === "pro" ? "Upgrade to Pro" : "Start free"}
              </Link>
            </div>
          ))}
        </div>

        <PricingDetail />

        {profile?.is_admin && (
          <div className="mt-10 text-center space-x-6">
            <Link
              href="/admin/pricing"
              className="text-teal-400 hover:text-teal-300 text-sm underline"
            >
              Edit pricing
            </Link>
            <Link
              href="/admin/editor"
              className="text-slate-400 hover:text-slate-300 text-sm underline"
            >
              Edit page content
            </Link>
          </div>
        )}
      </div>
    </div>
  );
}

import type { Metadata } from "next";
import { createClient } from "@supabase/supabase-js";
import { SharedSchedulePayload } from "@/lib/share/types";
import ShareRouteLinks from "@/components/share/ShareRouteLinks";
import RoundTimeline from "@/components/share/RoundTimeline";

// Never cached: a revoked or expired link must stop working immediately, not
// whenever a cache entry happens to fall out.
export const dynamic = "force-dynamic";
export const revalidate = 0;

// Belt and braces alongside the robots.txt disallow. A share link may be
// pasted into a group chat that pre-fetches URLs, so it must never be indexed
// even if a crawler reaches it directly.
export const metadata: Metadata = {
  title: "Your round",
  robots: { index: false, follow: false, nocache: true },
};

function serviceClient() {
  return createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
    { auth: { persistSession: false } }
  );
}

function Notice({ title, body }: { title: string; body: string }) {
  return (
    <div className="mx-auto max-w-lg px-4 py-24 text-center">
      <h1 className="mb-3 text-2xl font-semibold text-slate-100">{title}</h1>
      <p className="text-sm leading-relaxed text-slate-400">{body}</p>
    </div>
  );
}

export default async function SharedRoundPage({
  params,
}: {
  params: Promise<{ token: string }>;
}) {
  const { token } = await params;

  const { data, error } = await serviceClient()
    .from("shared_schedules")
    .select("staff_name, schedule_date, payload, expires_at, revoked")
    .eq("token", token)
    .maybeSingle();

  // One message for missing, revoked and expired alike -- distinguishing them
  // would tell someone probing tokens which ones were once real.
  const unavailable =
    error ||
    !data ||
    data.revoked ||
    new Date(data.expires_at).getTime() < Date.now();

  if (unavailable) {
    return (
      <div className="min-h-screen bg-slate-950 text-slate-100">
        <Notice
          title="This link is no longer available"
          body="It may have expired or been withdrawn. Ask whoever sent it for an up-to-date link."
        />
      </div>
    );
  }

  const payload = data.payload as SharedSchedulePayload;
  const stops = payload.stops ?? [];
  const breaks = payload.breaks ?? [];


  return (
    <div className="min-h-screen bg-slate-950 text-slate-100">
      <div className="mx-auto max-w-2xl px-4 py-10">
        <header className="mb-6">
          <h1 className="text-2xl font-semibold tracking-tight">
            {payload.staffName || data.staff_name || "Your round"}
          </h1>
          {data.schedule_date && (
            <p className="mt-1 text-sm text-slate-400">{data.schedule_date}</p>
          )}
          <p className="mt-1 text-xs text-slate-500">
            {stops.length} visit{stops.length === 1 ? "" : "s"}
            {breaks.length > 0 &&
              ` · ${breaks.length} break${breaks.length === 1 ? "" : "s"}`}
          </p>
        </header>

        <ShareRouteLinks payload={payload} />

        <RoundTimeline payload={payload} />

        <p className="mt-8 text-center text-[11px] leading-relaxed text-slate-600">
          This page contains personal information. Do not forward it. The link
          stops working on{" "}
          {new Date(data.expires_at).toLocaleDateString("en-GB")}.
        </p>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { supabase } from "@/lib/supabase/client";

export default function UpdatePasswordPage() {
  const [password, setPassword] = useState("");
  const [confirm, setConfirm] = useState("");
  const [message, setMessage] = useState("");
  const [loading, setLoading] = useState(false);
  const [sessionReady, setSessionReady] = useState(false);

  useEffect(() => {
    async function checkSession() {
      const { data } = await supabase.auth.getSession();
      if (data?.session) {
        setSessionReady(true);
      } else {
        setMessage("Invalid or expired reset link.");
      }
    }
    checkSession();
  }, []); // FIXED

  async function handleUpdate(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setMessage("");

    if (password !== confirm) {
      setMessage("Passwords do not match.");
      return;
    }

    setLoading(true);

    const { error } = await supabase.auth.updateUser({ password });

    if (error) {
      setMessage(error.message);
      setLoading(false);
      return;
    }

    setMessage("Password updated successfully. Redirecting to login...");
    setLoading(false);

    setTimeout(() => {
      window.location.href = "/login";
    }, 1500);
  }

  return (
    <div className="min-h-screen bg-slate-950 flex items-center justify-center px-4">
      <div className="w-full max-w-md bg-slate-900 border border-slate-800 rounded-xl p-8 shadow-xl">
        <h1 className="text-2xl font-semibold text-slate-50 text-center">
          Set a new password
        </h1>
        <p className="mt-2 text-sm text-slate-400 text-center">
          Enter your new password below.
        </p>

        {!sessionReady && (
          <p className="mt-6 text-center text-red-400">{message}</p>
        )}

        {sessionReady && (
          <form onSubmit={handleUpdate} className="mt-8 space-y-5">
            <div className="space-y-1">
              <label className="text-sm text-slate-300">New Password</label>
              <input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
                className="w-full rounded-md border border-slate-700 bg-slate-800 px-3 py-2 text-sm text-slate-50 outline-none focus:border-teal-400"
              />
            </div>

            <div className="space-y-1">
              <label className="text-sm text-slate-300">Confirm Password</label>
              <input
                type="password"
                value={confirm}
                onChange={(e) => setConfirm(e.target.value)}
                required
                className="w-full rounded-md border border-slate-700 bg-slate-800 px-3 py-2 text-sm text-slate-50 outline-none focus:border-teal-400"
              />
            </div>

            {message && (
              <p className="text-sm text-teal-300">{message}</p>
            )}

            <button
              type="submit"
              disabled={loading}
              className="w-full rounded-full bg-gradient-to-r from-green-500 via-teal-500 to-teal-400 px-4 py-2 text-sm font-medium text-slate-950 hover:brightness-110 transition disabled:opacity-50"
            >
              {loading ? "Updating..." : "Update Password"}
            </button>
          </form>
        )}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { supabase } from "@/lib/supabase/client";
import { useIsAdmin } from "@/lib/hooks/useIsAdmin";
import { HeaderStructure, NavItem, BrandConfig } from "./HeaderStructure";

export default function Header({
  logoUrl,
  bannerUrl,
  logo_x,
  logo_y,
  logo_scale,
  logo_rotation,
  banner_offset_x,
  banner_offset_y,
  banner_scale,
  banner_rotation,
  brand,
  navItems,
}: {
  logoUrl: string | null;
  bannerUrl: string | null;
  logo_x: number;
  logo_y: number;
  logo_scale: number;
  logo_rotation: number;
  banner_offset_x: number;
  banner_offset_y: number;
  banner_scale: number;
  banner_rotation: number;
  brand: BrandConfig;
  navItems: NavItem[];
}) {
  const isAdmin = useIsAdmin();
  const [user, setUser] = useState<{ id: string } | null>(null);
  const [profile, setProfile] = useState<{ is_pro?: boolean } | null>(null);

  useEffect(() => {
    async function load() {
      const { data: auth } = await supabase.auth.getUser();
      const u = auth?.user ?? null;
      setUser(u);

      if (u) {
        const { data: p } = await supabase
          .from("profiles")
          .select("*")
          .eq("user_id", u.id)
          .maybeSingle();

        setProfile(p || null);
      }
    }

    load();
  }, []);

  async function logout() {
    await supabase.auth.signOut();
    window.location.href = "/login";
  }

  const isPro = profile?.is_pro === true;

  return (
    <HeaderStructure
      logoUrl={logoUrl}
      bannerUrl={bannerUrl}
      logo_x={logo_x}
      logo_y={logo_y}
      logo_scale={logo_scale}
      logo_rotation={logo_rotation}
      banner_offset_x={banner_offset_x}
      banner_offset_y={banner_offset_y}
      banner_scale={banner_scale}
      banner_rotation={banner_rotation}
      brand={brand}
      navItems={navItems}
      userPresent={!!user}
      isPro={!!isPro}
      isAdmin={!!isAdmin}
      onLogout={logout}
    />
  );
}

"use client";

import Link from "next/link";
import Image from "next/image";
import { useState, useRef, useEffect } from "react";
import { useThemeStore } from "@/store/themeStore";
import SeasonalDoodle from "@/components/effects/SeasonalDoodle";

export type NavItem = {
  id: string;
  text: string;
  href: string;
  align?: "left" | "right";
  isAdmin?: boolean;
  /**
   * Show this item inside the menu dropdown rather than inline in the header.
   * Lets the bar stay short as pages are added, without hiding anything.
   */
  inMenu?: boolean;
};

export type BrandConfig = {
  enabled: boolean;
  text: string;
};

type Props = {
  logoUrl: string | null;
  bannerUrl: string | null;
  logo_x: number;
  logo_y: number;
  logo_scale: number;
  logo_rotation: number;
  banner_offset_x: number;
  banner_offset_y: number;
  banner_scale: number;
  banner_rotation: number;
  brand: BrandConfig;
  navItems: NavItem[];
  userPresent: boolean;
  isPro: boolean;
  isAdmin: boolean;
  onLogout: () => void;
};

/**
 * The admin sub-pages, in one place.
 *
 * This list was previously written out three times -- twice in the desktop
 * paths and not at all in the mobile one, which is how the mobile menu ended
 * up rendering "Admin" as an ordinary link to its placeholder href of "#".
 * Tapping it navigated nowhere and the sub-pages were unreachable on a phone.
 */
const ADMIN_LINKS: [string, string][] = [
  ["/admin/errors", "Errors"],
  ["/admin/users", "Users"],
  ["/admin/staff", "Staff"],
  ["/admin/appointments", "Appointments"],
  ["/admin/pricing", "Pricing"],
  ["/admin/logs", "Logs"],
  ["/admin/header-editor", "Header Editor"],
  ["/admin/themes", "Theme Builder"],
  ["/admin/editor", "Page Editor"],
];

export function HeaderStructure({
  logoUrl,
  bannerUrl,
  logo_x,
  logo_y,
  logo_scale,
  logo_rotation,
  banner_offset_x,
  banner_offset_y,
  banner_scale,
  banner_rotation,
  brand,
  navItems,
  userPresent,
  isPro,
  isAdmin,
  onLogout,
}: Props) {
  const [mobileOpen, setMobileOpen] = useState(false);
  const [adminOpen, setAdminOpen] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);

  // Closing used to be handled by onMouseLeave. With the menu opening on click
  // instead, it needs an explicit way out: a click anywhere else, or Escape.
  // Without this it could only be dismissed by hitting the same button again,
  // which is not where anyone's hand goes next.
  useEffect(() => {
    if (!menuOpen) return;

    const onPointerDown = (e: MouseEvent | TouchEvent) => {
      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
        setMenuOpen(false);
      }
    };
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") setMenuOpen(false);
    };

    document.addEventListener("mousedown", onPointerDown);
    document.addEventListener("touchstart", onPointerDown);
    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("mousedown", onPointerDown);
      document.removeEventListener("touchstart", onPointerDown);
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [menuOpen]);
  const { activeConfig } = useThemeStore();

  const leftNav = navItems.filter((n) => n.align !== "right" && !n.inMenu);
  const rightNav = navItems.filter((n) => n.align === "right" && !n.inMenu);
  // Everything flagged inMenu, wherever it was aligned, collects in the
  // dropdown. Admin-only entries are still filtered by isAdmin below.
  const menuNav = navItems.filter((n) => n.inMenu);

  return (
    <header className="relative w-full bg-slate-950 text-slate-100 border-b border-slate-800">
      {bannerUrl && (
        <div
          className="absolute inset-0 w-full h-full overflow-hidden pointer-events-none"
          style={{
            transform: `translate(${banner_offset_x}px, ${banner_offset_y}px) scale(${banner_scale}) rotate(${banner_rotation}deg)`,
            transformOrigin: "top left",
          }}
        >
          <Image
            src={bannerUrl}
            alt="Banner"
            fill
            className="object-cover opacity-40"
            priority
          />
        </div>
      )}

      <div className="relative max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
        <div className="flex items-center gap-6">
          <Link href="/" className="flex items-center gap-2 relative">
            {logoUrl && (
              <div
                className="relative inline-block"
                style={{
                  transform: `translate(${logo_x}px, ${logo_y}px) scale(${logo_scale}) rotate(${logo_rotation}deg)`,
                  transformOrigin: "top left",
                }}
              >
                {/* The header bar is 64px tall, so a fixed 100x100 logo was
                    being clipped top and bottom on every page. Height is
                    pinned to fit the bar and width follows the aspect ratio,
                    so any logo shape renders whole. */}
                {/* Decorative when the brand name is rendered as text beside
                    it -- announcing "Logo" and then the name repeats it. */}
                <Image
                  src={logoUrl}
                  alt={brand.enabled ? "" : brand.text || "GeoRoutes"}
                  width={200}
                  height={48}
                  className="h-10 w-auto max-w-[160px] object-contain"
                  priority
                />
              </div>
            )}

            {brand.enabled && (
              <span className="relative inline-flex items-end font-semibold text-lg tracking-tight">
                {activeConfig.logoDoodle !== "none" && (
                  <span
                    className="absolute pointer-events-none"
                    style={{ top: "-22px", left: "-4px" }}
                    aria-hidden
                  >
                    <SeasonalDoodle
                      doodle={activeConfig.logoDoodle}
                      color={activeConfig.logoDoodleColor}
                    />
                  </span>
                )}
                {brand.text}
              </span>
            )}
          </Link>

          <nav className="hidden md:flex items-center gap-6 text-sm">
            {leftNav.map((item) => {
              if (item.isAdmin && !isAdmin) return null;

              if (item.id === "admin") {
                return (
                  <div
                    key={item.id}
                    className="relative"
                    onMouseEnter={() => setAdminOpen(true)}
                    onMouseLeave={() => setAdminOpen(false)}
                  >
                    <button className="hover:text-teal-400">{item.text}</button>

                    {adminOpen && (
                      <div className="absolute left-0 top-full w-48 z-50 bg-slate-900 border border-slate-700 rounded shadow-lg py-2">
                        <Link href="/admin/users" className="block px-4 py-2 hover:bg-slate-800">Users</Link>
                        <Link href="/admin/staff" className="block px-4 py-2 hover:bg-slate-800">Staff</Link>
                        <Link href="/admin/appointments" className="block px-4 py-2 hover:bg-slate-800">Appointments</Link>
                        <Link href="/admin/pricing" className="block px-4 py-2 hover:bg-slate-800">Pricing</Link>
                        <Link href="/admin/logs" className="block px-4 py-2 hover:bg-slate-800">Logs</Link>
                        <Link href="/admin/header-editor" className="block px-4 py-2 hover:bg-slate-800">Header Editor</Link>
                        <Link href="/admin/themes" className="block px-4 py-2 hover:bg-slate-800">Theme Builder</Link>
                        <Link href="/admin/editor" className="block px-4 py-2 hover:bg-slate-800">Page Editor</Link>
                      </div>
                    )}
                  </div>
                );
              }

              return (
                <Link key={item.id} href={item.href} className="hover:text-teal-400">
                  {item.text}
                </Link>
              );
            })}
          </nav>
        </div>

        <div className="hidden md:flex items-center gap-4">
          {rightNav.map((item) => {
            if (item.isAdmin && !isAdmin) return null;

            if (item.id === "admin") {
              return (
                <div
                  key={item.id}
                  className="relative"
                  onMouseEnter={() => setAdminOpen(true)}
                  onMouseLeave={() => setAdminOpen(false)}
                >
                  <button className="hover:text-teal-400">{item.text}</button>

                  {adminOpen && (
                    <div className="absolute right-0 top-full w-48 z-50 bg-slate-900 border border-slate-700 rounded shadow-lg py-2">
                      <Link href="/admin/users" className="block px-4 py-2 hover:bg-slate-800">Users</Link>
                      <Link href="/admin/staff" className="block px-4 py-2 hover:bg-slate-800">Staff</Link>
                      <Link href="/admin/appointments" className="block px-4 py-2 hover:bg-slate-800">Appointments</Link>
                      <Link href="/admin/pricing" className="block px-4 py-2 hover:bg-slate-800">Pricing</Link>
                      <Link href="/admin/logs" className="block px-4 py-2 hover:bg-slate-800">Logs</Link>
                      <Link href="/admin/header-editor" className="block px-4 py-2 hover:bg-slate-800">Header Editor</Link>
                      <Link href="/admin/themes" className="block px-4 py-2 hover:bg-slate-800">Theme Builder</Link>
                      <Link href="/admin/editor" className="block px-4 py-2 hover:bg-slate-800">Page Editor</Link>
                    </div>
                  )}
                </div>
              );
            }

            return (
              <Link key={item.id} href={item.href} className="hover:text-teal-400 text-sm">
                {item.text}
              </Link>
            );
          })}

          {menuNav.length > 0 && (
            // Click to open, not hover. A tap on a touch device fires a
            // synthetic mouseenter and then a click, so hover-to-open plus
            // click-to-toggle meant the menu opened and immediately closed
            // again on a phone -- and a menu that opens on hover has no way to
            // be dismissed by keyboard either.
            <div className="relative" ref={menuRef}>
              <button
                type="button"
                onClick={() => setMenuOpen((o) => !o)}
                aria-expanded={menuOpen}
                aria-haspopup="true"
                aria-label="More"
                className="flex items-center gap-2 rounded px-2 py-2 text-sm hover:text-teal-400"
              >
                <span className="flex flex-col gap-[3px]">
                  <span className="block h-[2px] w-4 bg-current" />
                  <span className="block h-[2px] w-4 bg-current" />
                  <span className="block h-[2px] w-4 bg-current" />
                </span>
                Menu
              </button>

              {/* Rendered whether or not the menu is open, and hidden with CSS
                  rather than unmounted. Unmounting meant these links existed
                  only after a hover, so a crawler -- which does not hover --
                  saw a header containing four links and never followed Help or
                  anything else in here. The markup is identical either way, so
                  this is a visibility change, not a difference in what is
                  served to people and to crawlers. */}
              <div
                className={`absolute right-0 top-full z-50 w-52 rounded border border-slate-700 bg-slate-900 py-2 shadow-lg ${
                  menuOpen ? "" : "pointer-events-none invisible opacity-0"
                }`}
                aria-hidden={menuOpen ? undefined : true}
              >
                {(() => {
                  return menuNav.map((item) => {
                    if (item.isAdmin && !isAdmin) return null;

                    // The admin entry has sub-pages. Nesting a second dropdown
                    // inside this one would be awkward to use, so its links are
                    // listed flat under a heading instead.
                    if (item.id === "admin") {
                      return (
                        <div key={item.id} className="mt-1 border-t border-slate-800 pt-1">
                          <p className="px-4 py-1 text-[10px] uppercase tracking-widest text-slate-500">
                            {item.text}
                          </p>
                          {[
                            ["/admin/users", "Users"],
                            ["/admin/staff", "Staff"],
                            ["/admin/appointments", "Appointments"],
                            ["/admin/pricing", "Pricing"],
                            ["/admin/logs", "Logs"],
                            ["/admin/header-editor", "Header Editor"],
                            ["/admin/themes", "Theme Builder"],
                            ["/admin/editor", "Page Editor"],
                          ].map(([href, label]) => (
                            <Link
                              key={href}
                              href={href}
                              onClick={() => setMenuOpen(false)}
                              className="block px-4 py-2 text-sm hover:bg-slate-800"
                            >
                              {label}
                            </Link>
                          ))}
                        </div>
                      );
                    }

                    return (
                      <Link
                        key={item.id}
                        href={item.href}
                        onClick={() => setMenuOpen(false)}
                        className="block px-4 py-2 text-sm hover:bg-slate-800"
                      >
                        {item.text}
                      </Link>
                    );
                  });
                })()}
              </div>
            </div>
          )}

          {!userPresent && (
            <Link
              href="/login"
              className="px-4 py-2 bg-teal-500 text-slate-900 rounded font-medium hover:brightness-110"
            >
              Login
            </Link>
          )}

          {userPresent && (
            <button
              onClick={onLogout}
              className="px-4 py-2 bg-slate-800 rounded hover:bg-slate-700"
            >
              Logout
            </button>
          )}
        </div>

        <button
          className="md:hidden text-slate-300"
          onClick={() => setMobileOpen((v) => !v)}
        >
          {mobileOpen ? "✕" : "☰"}
        </button>

        {mobileOpen && (
          <div className="absolute top-16 inset-x-0 bg-slate-950 border-t border-slate-800 md:hidden z-50">
            <nav className="flex flex-col px-4 py-3 gap-2 text-sm">
              {brand.enabled && (
                <span className="py-1 font-semibold">{brand.text}</span>
              )}

              {navItems.map((item) => {
                if (item.isAdmin && !isAdmin) return null;

                // Admin is a heading with sub-pages, not a destination -- its
                // href is only ever "#". Rendered as a link, a tap went to "#"
                // and the sub-pages could not be reached from a phone at all.
                // Listed flat rather than behind a second toggle: a dropdown
                // inside an already-open menu is an extra tap for no benefit
                // when there is room to show the lot.
                if (item.id === "admin") {
                  return (
                    <div key={item.id} className="mt-1 border-t border-slate-800 pt-2">
                      <p className="py-1 text-[10px] uppercase tracking-widest text-slate-500">
                        {item.text}
                      </p>
                      {ADMIN_LINKS.map(([href, label]) => (
                        <Link
                          key={href}
                          href={href}
                          className="block py-1 pl-3 hover:text-teal-400"
                          onClick={() => setMobileOpen(false)}
                        >
                          {label}
                        </Link>
                      ))}
                    </div>
                  );
                }

                return (
                  <Link
                    key={item.id}
                    href={item.href}
                    className="py-1 hover:text-teal-400"
                    onClick={() => setMobileOpen(false)}
                  >
                    {item.text}
                  </Link>
                );
              })}

              {userPresent ? (
                <button
                  onClick={onLogout}
                  className="mt-2 text-left py-1 text-red-300"
                >
                  Logout
                </button>
              ) : (
                <Link
                  href="/login"
                  className="mt-2 py-1 text-teal-400"
                  onClick={() => setMobileOpen(false)}
                >
                  Login
                </Link>
              )}
            </nav>
          </div>
        )}
      </div>
    </header>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import Link from "next/link";
import { useAppointmentStore, Appointment } from "@/store/appointmentStore";
import { useExceptionStore } from "@/store/exceptionStore";
import {
  occurrencesBetween,
  toIsoDate,
  type RecurrenceRule,
} from "@/lib/recurrence/occurrences";
import MonthGrid, {
  buildCells,
  type DayCell,
  type CalendarView as ViewMode,
} from "./MonthGrid";

function ruleFor(a: Appointment): RecurrenceRule {
  return {
    freq: a.recurFreq ?? "once",
    interval: a.recurInterval ?? 1,
    weekdays: a.recurWeekdays ?? [],
    // Appointments predating recurrence have no start date. Anchoring them to
    // their own absent date would hide them, so they are treated as one-offs
    // on the grid's first day rather than vanishing.
    startsOn: a.startsOn ?? "1970-01-01",
    endsOn: a.endsOn ?? null,
  };
}

export default function CalendarView({ isFree }: { isFree: boolean }) {
  const { appointments } = useAppointmentStore();
  const { exceptions, forAppointment, skipOccurrence, moveOccurrence, clearException, load } =
    useExceptionStore();

  const todayIso = useMemo(() => toIsoDate(new Date()), []);
  const [view, setView] = useState<ViewMode>("month");
  // A single anchor date drives every view; each one just covers a different
  // span around it, and stepping moves by that view's own unit.
  const [anchor, setAnchor] = useState(todayIso);
  const [selected, setSelected] = useState<string | null>(todayIso);
  const [moveTarget, setMoveTarget] = useState<Record<string, string>>({});

  useEffect(() => {
    load(isFree);
  }, [isFree, load]);

  const baseCells = useMemo(
    () => buildCells(view, anchor, todayIso),
    [view, anchor, todayIso]
  );

  const active = useMemo(
    () => appointments.filter((a) => !a.archived),
    [appointments]
  );

  // Occurrences for the visible range, expanded once and bucketed by date.
  const { byDate, movedIntoDate } = useMemo(() => {
    const from = baseCells[0].iso;
    const to = baseCells[baseCells.length - 1].iso;

    const byDate = new Map<string, Appointment[]>();
    const movedIntoDate = new Map<string, number>();

    for (const a of active) {
      const exs = forAppointment(a.id);
      const dates = occurrencesBetween(ruleFor(a), exs, from, to);
      const movedTargets = new Set(
        exs.filter((e) => e.action === "move" && e.movedToDate).map((e) => e.movedToDate!)
      );

      for (const d of dates) {
        if (!byDate.has(d)) byDate.set(d, []);
        byDate.get(d)!.push(a);
        if (movedTargets.has(d)) {
          movedIntoDate.set(d, (movedIntoDate.get(d) ?? 0) + 1);
        }
      }
    }

    return { byDate, movedIntoDate };
  }, [active, baseCells, exceptions, forAppointment]);

  const cells: DayCell[] = baseCells.map((c) => ({
    ...c,
    names: (byDate.get(c.iso) ?? []).map((a) => a.name),
    movedIn: movedIntoDate.get(c.iso) ?? 0,
  }));

  const rangeLabel = (() => {
    const d = (iso: string) => new Date(`${iso}T12:00:00Z`);
    if (view === "month") {
      return d(anchor).toLocaleDateString("en-GB", { month: "long", year: "numeric" });
    }
    if (view === "day") {
      return d(anchor).toLocaleDateString("en-GB", {
        weekday: "long", day: "numeric", month: "long", year: "numeric",
      });
    }
    // A week can straddle two months, so show both ends rather than guessing.
    const first = baseCells[0].iso;
    const last = baseCells[baseCells.length - 1].iso;
    const opts = { day: "numeric", month: "short" } as const;
    const from = d(first).toLocaleDateString("en-GB", opts);
    const to = d(last).toLocaleDateString("en-GB", { ...opts, year: "numeric" });
    return `${from} – ${to}`;
  })();

  // Each view steps by its own unit: a month, a week, or a day.
  const step = (delta: number) =>
    setAnchor((current) => {
      const [y, m, dd] = current.split("-").map(Number);
      const d = new Date(Date.UTC(y, m - 1, dd, 12));
      if (view === "month") d.setUTCMonth(d.getUTCMonth() + delta);
      else if (view === "day") d.setUTCDate(d.getUTCDate() + delta);
      else d.setUTCDate(d.getUTCDate() + delta * 7);
      return toIsoDate(d);
    });

  const VIEWS: { id: ViewMode; label: string }[] = [
    { id: "month", label: "Month" },
    { id: "week", label: "Week" },
    { id: "workweek", label: "Working week" },
    { id: "day", label: "Day" },
  ];

  // In day view there is no grid to click, so the panel follows the anchor.
  // Elsewhere it follows the selected cell -- but only while that cell is
  // actually on screen. Paging away otherwise left the panel describing a day
  // the grid no longer showed.
  const focusedIso = (() => {
    if (view === "day") return anchor;
    const visible = new Set(baseCells.map((c) => c.iso));
    if (selected && visible.has(selected)) return selected;
    return visible.has(todayIso) ? todayIso : baseCells[0].iso;
  })();
  const selectedAppointments = focusedIso ? (byDate.get(focusedIso) ?? []) : [];

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h2 className="text-lg font-semibold text-slate-100">{rangeLabel}</h2>
        <div className="flex items-center gap-1">
          <button
            type="button"
            onClick={() => step(-1)}
            aria-label="Previous"
            className="rounded border border-slate-700 px-2 py-1 text-xs text-slate-300 hover:bg-slate-800"
          >
            ←
          </button>
          <button
            type="button"
            onClick={() => {
              setAnchor(todayIso);
              setSelected(todayIso);
            }}
            className="rounded border border-slate-700 px-2 py-1 text-xs text-slate-300 hover:bg-slate-800"
          >
            Today
          </button>
          <button
            type="button"
            onClick={() => step(1)}
            aria-label="Next"
            className="rounded border border-slate-700 px-2 py-1 text-xs text-slate-300 hover:bg-slate-800"
          >
            →
          </button>
        </div>
      </div>

      <div
        role="group"
        aria-label="Calendar view"
        className="flex flex-wrap gap-1"
      >
        {VIEWS.map((v) => (
          <button
            key={v.id}
            type="button"
            aria-pressed={view === v.id}
            // The anchor is left alone: it already tracks the period being
            // viewed, including after paging. Re-pointing it at 'selected'
            // here sent you back to whichever date was last clicked.
            onClick={() => setView(v.id)}
            className={`rounded border px-3 py-1 text-xs transition-colors ${
              view === v.id
                ? "border-teal-500 bg-teal-500/15 text-teal-200"
                : "border-slate-700 text-slate-300 hover:bg-slate-800"
            }`}
          >
            {v.label}
          </button>
        ))}
      </div>

      {/* The day view's single cell would just repeat the detail panel below. */}
      {view !== "day" && (
        <MonthGrid
          cells={cells}
          view={view}
          selectedIso={selected}
          onSelect={(iso) => {
            setSelected(iso);
            // Also the anchor, so switching to week or day view lands on the
            // day just clicked rather than wherever the period started.
            setAnchor(iso);
          }}
        />
      )}

      {focusedIso && (
        <div className="rounded-xl border border-slate-800 bg-slate-900/60 p-4">
          <div className="mb-3 flex flex-wrap items-center justify-between gap-2">
            <h3 className="text-sm font-semibold text-slate-100">
              {new Date(`${focusedIso}T12:00:00Z`).toLocaleDateString("en-GB", {
                weekday: "long",
                day: "numeric",
                month: "long",
              })}
            </h3>
            <Link
              href="/scheduler"
              className="rounded bg-teal-500 px-3 py-1 text-xs font-semibold text-slate-950 hover:bg-teal-400"
            >
              Plan this day
            </Link>
          </div>

          {selectedAppointments.length === 0 ? (
            <p className="text-xs text-slate-400">No visits due.</p>
          ) : (
            <ul className="space-y-2">
              {selectedAppointments.map((a) => {
                const exs = forAppointment(a.id);
                // A moved occurrence shows on its new date; the control there
                // has to clear the exception keyed to the ORIGINAL date.
                const movedHere = exs.find(
                  (e) => e.action === "move" && e.movedToDate === focusedIso
                );
                const key = `${a.id}|${focusedIso}`;

                return (
                  <li
                    key={a.id}
                    className="rounded border border-slate-800 bg-slate-900 px-3 py-2"
                  >
                    <div className="flex flex-wrap items-center justify-between gap-2">
                      <div className="min-w-0">
                        <span className="text-sm font-medium text-slate-100">
                          {a.name}
                        </span>
                        <span className="ml-2 text-xs text-slate-400">
                          {a.postcode} · {a.durationMinutes} min
                        </span>
                        {movedHere && (
                          <span className="ml-2 text-xs text-amber-300">
                            moved from {movedHere.onDate}
                          </span>
                        )}
                      </div>

                      <div className="flex items-center gap-1">
                        {movedHere ? (
                          <button
                            type="button"
                            onClick={() => clearException(a.id, movedHere.onDate)}
                            className="rounded border border-slate-700 px-2 py-1 text-[11px] text-slate-300 hover:bg-slate-800"
                          >
                            Undo move
                          </button>
                        ) : (
                          <>
                            <input
                              type="date"
                              value={moveTarget[key] ?? ""}
                              onChange={(e) =>
                                setMoveTarget((m) => ({ ...m, [key]: e.target.value }))
                              }
                              aria-label={`Move ${a.name} to a different date`}
                              className="rounded border border-slate-700 bg-slate-900 px-1.5 py-1 text-[11px] text-slate-200"
                            />
                            <button
                              type="button"
                              disabled={!moveTarget[key]}
                              onClick={() =>
                                moveOccurrence(a.id, focusedIso, moveTarget[key])
                              }
                              className="rounded border border-slate-700 px-2 py-1 text-[11px] text-slate-300 hover:bg-slate-800 disabled:opacity-40"
                            >
                              Move
                            </button>
                            <button
                              type="button"
                              onClick={() => skipOccurrence(a.id, focusedIso)}
                              className="rounded border border-slate-700 px-2 py-1 text-[11px] text-slate-300 hover:border-red-500/60 hover:text-red-300"
                            >
                              Skip
                            </button>
                          </>
                        )}
                      </div>
                    </div>
                  </li>
                );
              })}
            </ul>
          )}

          <p className="mt-3 text-[11px] leading-relaxed text-slate-500">
            Skipping or moving affects only this one occurrence. The rest of the
            series is unchanged.
          </p>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";
import { Effect } from "@/lib/theme-types";

interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
  opacity: number;
  color: string;
  rotation?: number;
  vr?: number;
  life?: number;
  maxLife?: number;
}

interface Props {
  effect: Effect;
  intensity: number;
  color: string;
}

export default function ParticleCanvas({ effect, intensity, color }: Props) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const rafRef = useRef<number>(0);
  const particlesRef = useRef<Particle[]>([]);

  useEffect(() => {
    if (effect === "none") return;

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const count = Math.round((intensity / 100) * getMaxParticles(effect));

    function resize() {
      if (!canvas) return;
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    resize();
    window.addEventListener("resize", resize);

    // Initialise particle pool
    particlesRef.current = Array.from({ length: count }, () =>
      makeParticle(effect, color, canvas!.width, canvas!.height)
    );

    function tick() {
      if (!canvas || !ctx) return;
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      for (const p of particlesRef.current) {
        updateParticle(p, effect, canvas.width, canvas.height, color);
        drawParticle(ctx, p, effect);
      }

      rafRef.current = requestAnimationFrame(tick);
    }
    tick();

    return () => {
      window.removeEventListener("resize", resize);
      cancelAnimationFrame(rafRef.current);
      particlesRef.current = [];
    };
  }, [effect, intensity, color]);

  if (effect === "none") return null;

  return (
    <canvas
      ref={canvasRef}
      className="fixed inset-0 pointer-events-none"
      style={{ zIndex: 9999 }}
    />
  );
}

function getMaxParticles(effect: Effect): number {
  switch (effect) {
    case "snow": return 150;
    case "rain": return 200;
    case "confetti": return 120;
    case "fireflies": return 40;
    case "stars": return 80;
    case "hearts": return 50;
    case "leaves": return 60;
    default: return 60;
  }
}

function makeParticle(
  effect: Effect,
  color: string,
  w: number,
  h: number
): Particle {
  switch (effect) {
    case "snow":
      return {
        x: Math.random() * w,
        y: Math.random() * h - h,
        vx: (Math.random() - 0.5) * 0.6,
        vy: Math.random() * 1.5 + 0.5,
        radius: Math.random() * 3 + 1,
        opacity: Math.random() * 0.6 + 0.4,
        color,
      };
    case "rain":
      return {
        x: Math.random() * w,
        y: Math.random() * h - h,
        vx: -0.5,
        vy: Math.random() * 8 + 10,
        radius: Math.random() * 0.8 + 0.4,
        opacity: Math.random() * 0.4 + 0.3,
        color,
      };
    case "confetti": {
      const hue = Math.random() * 360;
      return {
        x: Math.random() * w,
        y: Math.random() * h - h,
        vx: (Math.random() - 0.5) * 2,
        vy: Math.random() * 3 + 2,
        radius: Math.random() * 5 + 3,
        opacity: 1,
        color: `hsl(${hue},80%,60%)`,
        rotation: Math.random() * Math.PI * 2,
        vr: (Math.random() - 0.5) * 0.2,
      };
    }
    case "fireflies":
      return {
        x: Math.random() * w,
        y: Math.random() * h,
        vx: (Math.random() - 0.5) * 0.4,
        vy: (Math.random() - 0.5) * 0.4,
        radius: Math.random() * 2 + 1.5,
        opacity: 0,
        color,
        life: Math.random() * Math.PI * 2,
        maxLife: Math.PI * 2,
      };
    case "stars":
      return {
        x: Math.random() * w,
        y: Math.random() * h,
        vx: 0,
        vy: 0,
        radius: Math.random() * 1.5 + 0.5,
        opacity: Math.random() * 0.8 + 0.2,
        color,
        life: Math.random() * Math.PI * 2,
        maxLife: Math.PI * 2,
      };
    case "hearts":
      return {
        x: Math.random() * w,
        y: Math.random() * h + h,
        vx: (Math.random() - 0.5) * 0.6,
        vy: -(Math.random() * 1.5 + 0.5),
        radius: Math.random() * 8 + 4,
        opacity: Math.random() * 0.5 + 0.3,
        color,
      };
    case "leaves": {
      const hue = 100 + Math.random() * 60;
      return {
        x: Math.random() * w,
        y: Math.random() * h - h,
        vx: (Math.random() - 0.5) * 1.5,
        vy: Math.random() * 1.5 + 0.5,
        radius: Math.random() * 7 + 4,
        opacity: Math.random() * 0.6 + 0.4,
        color: `hsl(${hue},60%,50%)`,
        rotation: Math.random() * Math.PI * 2,
        vr: (Math.random() - 0.5) * 0.05,
      };
    }
    default:
      return { x: 0, y: 0, vx: 0, vy: 0, radius: 2, opacity: 0.5, color };
  }
}

function updateParticle(
  p: Particle,
  effect: Effect,
  w: number,
  h: number,
  color: string
) {
  switch (effect) {
    case "snow":
      p.x += p.vx + Math.sin(Date.now() * 0.001 + p.y * 0.01) * 0.3;
      p.y += p.vy;
      if (p.y > h + 10) {
        p.y = -10;
        p.x = Math.random() * w;
      }
      break;
    case "rain":
      p.x += p.vx;
      p.y += p.vy;
      if (p.y > h) {
        p.y = -20;
        p.x = Math.random() * w;
      }
      break;
    case "confetti":
      p.x += p.vx;
      p.y += p.vy;
      p.vy += 0.02;
      if (p.rotation !== undefined && p.vr !== undefined) p.rotation += p.vr;
      if (p.y > h + 20) {
        p.y = -10;
        p.x = Math.random() * w;
        p.vy = Math.random() * 2 + 1;
      }
      break;
    case "fireflies":
      p.x += p.vx + Math.sin(Date.now() * 0.0005 + p.y) * 0.3;
      p.y += p.vy + Math.cos(Date.now() * 0.0005 + p.x) * 0.3;
      if (p.life !== undefined) {
        p.life += 0.04;
        p.opacity = (Math.sin(p.life) + 1) * 0.5;
      }
      if (p.x < 0 || p.x > w || p.y < 0 || p.y > h) {
        p.x = Math.random() * w;
        p.y = Math.random() * h;
      }
      break;
    case "stars":
      if (p.life !== undefined) {
        p.life += 0.02;
        p.opacity = ((Math.sin(p.life) + 1) / 2) * 0.7 + 0.1;
      }
      break;
    case "hearts":
      p.x += p.vx + Math.sin(Date.now() * 0.001 + p.y * 0.01) * 0.3;
      p.y += p.vy;
      p.opacity -= 0.003;
      if (p.y < -20 || p.opacity <= 0) {
        p.y = h + 20;
        p.x = Math.random() * w;
        p.opacity = Math.random() * 0.5 + 0.3;
        p.vy = -(Math.random() * 1.5 + 0.5);
      }
      break;
    case "leaves":
      p.x += p.vx + Math.sin(Date.now() * 0.001 + p.y * 0.02) * 0.5;
      p.y += p.vy;
      if (p.rotation !== undefined && p.vr !== undefined) p.rotation += p.vr;
      if (p.y > h + 20) {
        p.y = -10;
        p.x = Math.random() * w;
      }
      break;
  }
}

function drawParticle(ctx: CanvasRenderingContext2D, p: Particle, effect: Effect) {
  ctx.save();
  ctx.globalAlpha = Math.max(0, Math.min(1, p.opacity));

  switch (effect) {
    case "snow":
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
      ctx.fillStyle = p.color;
      ctx.shadowColor = p.color;
      ctx.shadowBlur = 4;
      ctx.fill();
      break;

    case "rain": {
      ctx.strokeStyle = p.color;
      ctx.lineWidth = p.radius;
      ctx.beginPath();
      ctx.moveTo(p.x, p.y);
      ctx.lineTo(p.x + 1, p.y - 12);
      ctx.stroke();
      break;
    }

    case "confetti":
      ctx.translate(p.x, p.y);
      ctx.rotate(p.rotation ?? 0);
      ctx.fillStyle = p.color;
      ctx.fillRect(-p.radius / 2, -p.radius / 2, p.radius, p.radius * 1.6);
      break;

    case "fireflies":
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
      ctx.fillStyle = p.color;
      ctx.shadowColor = p.color;
      ctx.shadowBlur = 12;
      ctx.fill();
      break;

    case "stars":
      drawStar(ctx, p.x, p.y, p.radius * 2, p.color);
      break;

    case "hearts":
      drawHeart(ctx, p.x, p.y, p.radius, p.color);
      break;

    case "leaves":
      ctx.translate(p.x, p.y);
      ctx.rotate(p.rotation ?? 0);
      ctx.beginPath();
      ctx.ellipse(0, 0, p.radius * 0.5, p.radius, 0, 0, Math.PI * 2);
      ctx.fillStyle = p.color;
      ctx.fill();
      break;
  }

  ctx.restore();
}

function drawStar(ctx: CanvasRenderingContext2D, x: number, y: number, r: number, color: string) {
  ctx.save();
  ctx.fillStyle = color;
  ctx.shadowColor = color;
  ctx.shadowBlur = 6;
  ctx.beginPath();
  for (let i = 0; i < 5; i++) {
    const outer = (i * Math.PI * 2) / 5 - Math.PI / 2;
    const inner = outer + Math.PI / 5;
    if (i === 0) ctx.moveTo(x + r * Math.cos(outer), y + r * Math.sin(outer));
    else ctx.lineTo(x + r * Math.cos(outer), y + r * Math.sin(outer));
    ctx.lineTo(x + (r / 2) * Math.cos(inner), y + (r / 2) * Math.sin(inner));
  }
  ctx.closePath();
  ctx.fill();
  ctx.restore();
}

function drawHeart(ctx: CanvasRenderingContext2D, x: number, y: number, r: number, color: string) {
  ctx.save();
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.moveTo(x, y + r * 0.3);
  ctx.bezierCurveTo(x - r, y - r * 0.5, x - r * 1.5, y + r * 0.5, x, y + r * 1.2);
  ctx.bezierCurveTo(x + r * 1.5, y + r * 0.5, x + r, y - r * 0.5, x, y + r * 0.3);
  ctx.fill();
  ctx.restore();
}

