"use client";

import {
  MapContainer,
  Marker,
  Popup,
  Polyline,
  Tooltip,
  useMap,
  ZoomControl,
} from "react-leaflet";
import "leaflet/dist/leaflet.css";
import styles from "./MapVisualizer.module.css";

import { useEffect, useMemo, useRef, useState } from "react";
import { supabase } from "@/lib/supabase/client";
import { useHighlightStore } from "@/lib/map/highlightStore";
import { applyStaffColors } from "@/lib/map/staffColorMap";
import { loadFreeSchedulerData } from "@/lib/freeSession";
import { useUserTier } from "@/lib/hooks/useUserTier";
import { geocodePostcodes } from "@/lib/geocode";
import { ScheduledVisit } from "@/lib/scheduler/types";
import { Staff } from "@/store/staffStore";
import { useSettingsStore } from "@/store/settingsStore";
import { LEG_COLORS } from "@/lib/map/legColors";
import { buildPinIcon } from "@/lib/map/pinIcons";
import { StaffLeg, RETURN_TO_BASE_ID } from "@/lib/map/useStaffLegSchedule";
import { getStaffOriginPostcode } from "@/lib/scheduler/staffOrigin";

import L from "leaflet";

const GLOBAL_PIN_COLOR = "#2563eb";
const ORIGIN_PIN_COLOR = "#1e293b";

function fmtTime(d: Date | null): string {
  if (!d) return "";
  return d.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
}

const iconUrl =
  "https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon.png";
const iconShadow =
  "https://unpkg.com/leaflet@1.9.4/dist/images/marker-shadow.png";

const DefaultIcon = L.icon({ iconUrl, shadowUrl: iconShadow });
L.Marker.prototype.options.icon = DefaultIcon;

// ─── Types ────────────────────────────────────────────────────────────────────

// One leg = a single travel segment between two consecutive stops.
// office departure has fromVisitId=null; office return has toVisitId=null.
type RouteLeg = {
  id: string;
  staffId: string;
  color: string;
  points: [number, number][];
  fromVisitId: string | null;
  toVisitId: string | null;
  fromPostcode: string;
  toPostcode: string;
  legIndex: number;
};

type AppointmentMarker = {
  id: string;
  staffId: string;
  lat: number;
  lng: number;
  clientName: string;
  postcode: string;
  address?: string;
  time: string;
  staffName: string;
  windowName?: string;
  color: string;
  durationMins: number;
  coStaff: string[];
  /** 1-based position in that staff member's day, used as the pin badge. */
  seq: number;
};

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * A stored route, from either the routes table or a free-mode session.
 *
 * Both sources predate the per-leg model the map uses now, and neither is
 * validated on the way in, so every field is treated as possibly absent. These
 * feed the "legacy" loading paths below, which exist for schedules saved
 * before legs were introduced.
 */
interface StoredRoute {
  id: string;
  staff_id?: string | null;
  points?: unknown;
}

/** A coloured StoredRoute, after applyStaffColors has run over it. */
interface ColouredRoute {
  id: string;
  staff_id?: string | null;
  color: string;
  points: [number, number][];
}

/** An appointment as free mode stored it, before the current marker shape. */
interface StoredAppointment {
  id: string;
  staffId?: string;
  lat?: number;
  lng?: number;
  // Both longitude spellings and both name spellings appear in stored data,
  // which is the reason this shape needed writing down rather than guessing.
  lon?: number;
  clientName?: string;
  name?: string;
  label?: string;
  postcode?: string;
  time?: string;
  staffName?: string;
  color?: string;
}

/**
 * A coordinate as it might arrive from any of the sources feeding this map.
 *
 * Every spelling is optional because the point of normalizePoints is that the
 * caller does not know which one it has -- routing responses, cached rows and
 * geocoded results have each used different names over time.
 */
interface LooseCoordinate {
  lat?: number | null;
  latitude?: number | null;
  y?: number | null;
  lng?: number | null;
  lon?: number | null;
  longitude?: number | null;
  x?: number | null;
}

function normalizePoints(raw: unknown): [number, number][] {
  if (!Array.isArray(raw)) return [];
  return raw
    .map((point) => {
      const p = point as LooseCoordinate | null | undefined;
      if (!p) return null;
      const lat = p.lat ?? p.latitude ?? p.y ?? null;
      const lng = p.lng ?? p.lon ?? p.longitude ?? p.x ?? null;
      if (lat == null || lng == null) return null;
      return [lat, lng] as [number, number];
    })
    .filter((p): p is [number, number] => p !== null);
}

// ─── Map sub-components ───────────────────────────────────────────────────────

/**
 * Leaflet's map instance, plus the two markers this component parks on it.
 *
 * Leaflet has no state of its own for "have I already set this up", and the
 * map object outlives React's effects -- so initialisation is recorded on the
 * instance itself. Declaring the fields is what replaces four `as any` casts;
 * the underscore prefix follows Leaflet's own convention for internals.
 */
type InitialisedMap = ReturnType<typeof useMap> & {
  _initialized?: boolean;
  _tileLayer?: ReturnType<typeof L.tileLayer>;
};

function MapInitializer({ zoom }: { zoom: number }) {
  const map = useMap() as InitialisedMap;
  useEffect(() => {
    if (map._initialized) return;
    map._initialized = true;
    map.setView([53.0, -2.2], zoom);
    map.zoomControl.remove();
    if (!map._tileLayer) {
      const tileLayer = L.tileLayer(
        "https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",
        { attribution: "&copy; OpenStreetMap contributors" }
      );
      tileLayer.addTo(map);
      map._tileLayer = tileLayer;
    }
  }, [map, zoom]);
  return null;
}

function StableMapWrapper({ children }: { children: React.ReactNode }) {
  const ref = useRef<HTMLDivElement | null>(null);
  const [ready, setReady] = useState(false);
  useEffect(() => {
    if (ref.current && !ready) setReady(true);
  }, [ref.current, ready]);
  return (
    <div ref={ref} className={styles.wrapper}>
      {ready && children}
    </div>
  );
}

// Handles map camera: zooms to selected visit's surrounding legs,
// or fits all legs for the selected staff member.
function FocusManager({
  selectedStaffId,
  selectedVisitId,
  legs,
  markers,
  officeGeo,
}: {
  selectedStaffId?: string | null;
  selectedVisitId?: string | null;
  legs: RouteLeg[];
  markers: AppointmentMarker[];
  officeGeo: { lat: number; lng: number } | null;
}) {
  const map = useMap();
  const hasInitialFit = useRef(false);

  // Reset flag when schedule is cleared so a fresh generate re-fits
  useEffect(() => {
    if (legs.length === 0) hasInitialFit.current = false;
  }, [legs.length]);

  // Initial overview: fit everything into view once legs first populate
  useEffect(() => {
    if (hasInitialFit.current) return;
    if (selectedStaffId || selectedVisitId) return;
    if (legs.length === 0) return;

    const pts = [] as ReturnType<typeof L.latLng>[];
    legs.forEach((l) => l.points.forEach((p) => pts.push(L.latLng(p[0], p[1]))));
    markers.forEach((m) => pts.push(L.latLng(m.lat, m.lng)));
    if (officeGeo) pts.push(L.latLng(officeGeo.lat, officeGeo.lng));

    if (pts.length > 0) {
      map.fitBounds(L.latLngBounds(pts), { padding: [50, 50] });
      hasInitialFit.current = true;
    }
  }, [legs, markers, officeGeo, selectedStaffId, selectedVisitId, map]);

  // Selection focus: visit or staff
  useEffect(() => {
    if (selectedVisitId) {
      // Only the arrival leg is rendered in visit view now, so only fit to that.
      // RETURN_TO_BASE_ID selects the final leg back to home/office instead.
      const isReturn = selectedVisitId === RETURN_TO_BASE_ID;
      const surroundingLegs = legs.filter((l) =>
        isReturn
          ? l.toVisitId === null && l.staffId === selectedStaffId
          : l.toVisitId === selectedVisitId
      );
      const pts = surroundingLegs.flatMap((l) =>
        l.points.map((p) => L.latLng(p[0], p[1]))
      );
      if (!isReturn) {
        const marker = markers.find((m) => m.id === selectedVisitId);
        if (marker) pts.push(L.latLng(marker.lat, marker.lng));
      }
      if (pts.length > 0)
        map.fitBounds(L.latLngBounds(pts), { padding: [60, 60] });
      return;
    }

    if (selectedStaffId) {
      const staffLegs = legs.filter(
        (l) => l.staffId === selectedStaffId && l.points.length > 0
      );
      const pts = staffLegs.flatMap((l) =>
        l.points.map((p) => L.latLng(p[0], p[1]))
      );
      if (pts.length > 0)
        map.fitBounds(L.latLngBounds(pts), { padding: [40, 40] });
    }
  }, [selectedStaffId, selectedVisitId, legs, markers, map]);

  return null;
}

// Shared rich popup body for a single appointment marker.
/**
 * Keep Leaflet's idea of its own size in step with the element.
 *
 * Leaflet measures its container once, on mount, and never looks again. The
 * results column beside this map grows with the number of visits, which
 * stretches the map's container after that measurement -- so the tiles kept
 * covering only the area the box had when it first rendered, leaving the rest
 * of a tall box blank.
 */
function KeepMapSized() {
  const map = useMap();

  useEffect(() => {
    const el = map.getContainer();

    const observer = new ResizeObserver(() => map.invalidateSize());
    observer.observe(el);

    // The first measurement can land before the surrounding layout settles,
    // so take one more reading on the next frame.
    const raf = requestAnimationFrame(() => map.invalidateSize());

    return () => {
      observer.disconnect();
      cancelAnimationFrame(raf);
    };
  }, [map]);

  return null;
}

function AppointmentPopup({ a }: { a: AppointmentMarker }) {
  return (
    <Popup>
      <div style={{ fontSize: 12, lineHeight: 1.6, minWidth: 160 }}>
        <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 3 }}>
          {a.clientName}
        </div>
        {a.windowName && (
          <div style={{ color: "#2563eb", fontWeight: 600, marginBottom: 3 }}>
            {a.windowName}
          </div>
        )}
        {a.address && <div style={{ color: "#475569" }}>{a.address}</div>}
        <div style={{ color: "#475569" }}>{a.postcode}</div>
        <div style={{ color: "#475569" }}>
          {a.time} · {a.durationMins} min
        </div>
        <div
          style={{
            marginTop: 5,
            borderTop: "1px solid #e2e8f0",
            paddingTop: 4,
            color: "#64748b",
          }}
        >
          <span style={{ fontWeight: 600 }}>Staff:</span> {a.staffName}
        </div>
        {a.coStaff.length > 0 && (
          <div style={{ color: "#64748b" }}>
            <span style={{ fontWeight: 600 }}>Also:</span> {a.coStaff.join(", ")}
          </div>
        )}
      </div>
    </Popup>
  );
}

// ─── Main component ───────────────────────────────────────────────────────────

export default function MapVisualizerInner({
  zoom = 12,
  showRoutes = true,
  showAppointments = true,
  selectedStaffId,
  selectedVisitId,
  scheduledVisits,
  staffList,
  staffLegSchedule,
  legScheduleLoading,
}: {
  zoom?: number;
  showRoutes?: boolean;
  showAppointments?: boolean;
  showStaffRoutes?: boolean; // kept for API compat
  selectedStaffId?: string | null;
  selectedVisitId?: string | null;
  scheduledVisits?: ScheduledVisit[];
  staffList?: Staff[];
  staffLegSchedule?: StaffLeg[];
  legScheduleLoading?: boolean;
}) {
  const isFree = useUserTier();

  const highlightedAppointmentId = useHighlightStore(
    (s) => s.highlightedAppointmentId
  );
  const setHighlightedAppointment = useHighlightStore(
    (s) => s.setHighlightedAppointment
  );
  const highlightedRouteId = useHighlightStore((s) => s.highlightedRouteId);
  const setHighlightedRoute = useHighlightStore((s) => s.setHighlightedRoute);

  const [legs, setLegs] = useState<RouteLeg[]>([]);
  const [appointments, setAppointments] = useState<AppointmentMarker[]>([]);
  const [officeGeo, setOfficeGeo] = useState<{ lat: number; lng: number } | null>(null);

  const geoMapRef = useRef<Map<string, { lat: number; lng: number }>>(new Map());
  const baseLegsRef = useRef<RouteLeg[]>([]);

  const [mapKey] = useState(() => crypto.randomUUID());
  const channelRef = useRef<ReturnType<typeof supabase.channel> | null>(null);
  const officePost = useSettingsStore((s) => s.settings.officePostcode);

  // ── EFFECT 1: geocode postcodes → markers + straight-line legs ──────────────
  useEffect(() => {
    if (scheduledVisits === undefined) return;

    if (scheduledVisits.length === 0) {
      setAppointments([]);
      setLegs([]);
      baseLegsRef.current = [];
      return;
    }

    const allPostcodes = [
      ...new Set([
        ...scheduledVisits.map((v) => v.postcode).filter(Boolean),
        ...(officePost ? [officePost] : []),
        ...(staffList ?? []).map((s) => s.homePostcode).filter(Boolean),
        ...(staffList ?? []).map((s) => s.officePostcode).filter(Boolean),
      ]),
    ];

    geocodePostcodes(allPostcodes).then((geoMap) => {
      geoMapRef.current = geoMap;
      setOfficeGeo(officePost ? (geoMap.get(officePost.toUpperCase()) ?? null) : null);

      const fmt = (iso: string) =>
        new Date(iso).toLocaleTimeString([], {
          hour: "2-digit",
          minute: "2-digit",
        });

      // ── Build per-staff visit order so each visit knows its leg-index ──
      const visitDayIndex = new Map<string, number>(); // visitId → 0-based index in staff's day
      {
        const staffGroups = new Map<string, ScheduledVisit[]>();
        for (const v of scheduledVisits) {
          if (!staffGroups.has(v.staffId)) staffGroups.set(v.staffId, []);
          staffGroups.get(v.staffId)!.push(v);
        }
        for (const group of staffGroups.values()) {
          group
            .sort((a, b) => new Date(a.start).getTime() - new Date(b.start).getTime())
            .forEach((v, i) => visitDayIndex.set(v.id, i));
        }
      }

      // ── Markers: one per visit ──
      // Deliberately NOT offsetting markers that share a postcode: route
      // polylines (built independently in useStaffLegSchedule) always
      // terminate at the exact geocoded point, so any offset here would make
      // pins visibly disconnect from the lines that lead to them.
      const markers: AppointmentMarker[] = scheduledVisits.map((v) => {
        const pc = v.postcode.toUpperCase();
        const geo = geoMap.get(pc);
        const durationMins = Math.round(
          (new Date(v.end).getTime() - new Date(v.start).getTime()) / 60000
        );
        const coStaff = scheduledVisits
          .filter(
            (o) => o.appointmentId === v.appointmentId && o.staffId !== v.staffId
          )
          .map((o) => o.staffName);
        // Color matches the incoming leg (leg index = visit's day position)
        const legIdx = visitDayIndex.get(v.id) ?? 0;
        const color = LEG_COLORS[legIdx % LEG_COLORS.length];

        return {
          id: v.id,
          staffId: v.staffId,
          lat: geo?.lat ?? 53.0,
          lng: geo?.lng ?? -2.2,
          clientName: v.clientName,
          postcode: v.postcode,
          address: v.address,
          time: `${fmt(v.start)}–${fmt(v.end)}`,
          staffName: v.staffName,
          windowName: v.windowName,
          color,
          durationMins,
          coStaff,
          seq: legIdx + 1,
        };
      });

      // ── Legs: home → v1 → v2 → ... → vN → home (per staff) ──
      const sorted = [...scheduledVisits].sort(
        (a, b) => new Date(a.start).getTime() - new Date(b.start).getTime()
      );
      const staffIds = [...new Set(sorted.map((v) => v.staffId))];

      const newLegs: RouteLeg[] = [];

      for (const staffId of staffIds) {
        const staffVisits = sorted.filter((v) => v.staffId === staffId);
        const staffMember = staffList?.find((s) => s.id === staffId);

        type SeqStop = {
          visitId: string | null;
          postcode: string;
          geo: { lat: number; lng: number } | null;
        };

        const homePost = staffMember
          ? getStaffOriginPostcode(staffMember, officePost).toUpperCase()
          : officePost?.toUpperCase() || "";
        const homeGeo = homePost ? (geoMap.get(homePost) ?? null) : null;

        const homeStop: SeqStop = {
          visitId: null,
          postcode: homePost,
          geo: homeGeo,
        };

        const sequence: SeqStop[] = [
          homeStop,
          ...staffVisits.map((v) => ({
            visitId: v.id,
            postcode: v.postcode,
            geo: geoMap.get(v.postcode.toUpperCase()) ?? null,
          })),
          homeStop,
        ];

        for (let i = 0; i < sequence.length - 1; i++) {
          const from = sequence[i];
          const to = sequence[i + 1];
          const points: [number, number][] = [];
          if (from.geo) points.push([from.geo.lat, from.geo.lng]);
          if (to.geo) points.push([to.geo.lat, to.geo.lng]);

          newLegs.push({
            id: `${staffId}-leg-${i}`,
            staffId,
            color: LEG_COLORS[i % LEG_COLORS.length],
            points,
            fromVisitId: from.visitId,
            toVisitId: to.visitId,
            fromPostcode: from.postcode,
            toPostcode: to.postcode,
            legIndex: i,
          });
        }
      }

      baseLegsRef.current = newLegs;
      setAppointments(markers);
      setLegs(newLegs);
    });
  }, [scheduledVisits, staffList, officePost]);

  // ── EFFECT 2: legacy loading (when scheduledVisits not provided) ─────────────
  useEffect(() => {
    if (scheduledVisits !== undefined) return;

    async function loadFree() {
      const data = await loadFreeSchedulerData();
      const freeRoutesRaw = data?.routes ?? [];
      const freeAppointmentsRaw = data?.appointments ?? [];

      const normalizedRoutes = (freeRoutesRaw ?? []).map((r: StoredRoute) => ({
        id: r.id,
        staff_id: r.staff_id ?? null,
        points: normalizePoints(r.points ?? []),
      }));
      const colored = applyStaffColors(normalizedRoutes);

      // Convert legacy routes to single-leg format
      const legacyLegs: RouteLeg[] = colored.map((r: ColouredRoute) => ({
        id: r.id,
        staffId: r.staff_id ?? r.id,
        color: r.color,
        points: r.points,
        fromVisitId: null,
        toVisitId: null,
        fromPostcode: "",
        toPostcode: "",
        legIndex: 0,
      }));

      const legacyMarkers: AppointmentMarker[] = (freeAppointmentsRaw ?? []).map(
        (a: StoredAppointment) => ({
          id: a.id,
          staffId: a.staffId ?? "",
          lat: a.lat ?? 53.0,
          lng: a.lng ?? -2.2,
          clientName: a.clientName ?? a.label ?? "Appointment",
          postcode: a.postcode ?? "",
          time: a.time ?? "",
          staffName: a.staffName ?? "",
          color: a.color ?? "#d00000",
          durationMins: 0,
          coStaff: [],
          seq: 0,
        })
      );

      setLegs(legacyLegs);
      setAppointments(legacyMarkers);
    }

    async function loadPro() {
      async function loadRoutes() {
        const { data } = await supabase.from("routes").select("*");
        const normalized = (data ?? []).map((r: StoredRoute) => ({
          id: r.id,
          staff_id: r.staff_id ?? null,
          points: normalizePoints(r.points ?? []),
        }));
        const colored = applyStaffColors(normalized);
        const legacyLegs: RouteLeg[] = colored.map((r: ColouredRoute) => ({
          id: r.id,
          staffId: r.staff_id ?? r.id,
          color: r.color,
          points: r.points,
          fromVisitId: null,
          toVisitId: null,
          fromPostcode: "",
          toPostcode: "",
          legIndex: 0,
        }));
        setLegs(legacyLegs);
      }

      async function loadAppointments() {
        const { data } = await supabase.from("appointments").select("*");
        setAppointments(
          (data ?? []).map((a: StoredAppointment) => ({
            id: a.id,
            staffId: a.staffId ?? "",
            lat: a.lat ?? 53.0,
            lng: a.lon ?? -2.2,
            clientName: a.clientName ?? a.name ?? "Appointment",
            postcode: a.postcode ?? "",
            time: a.time ?? "",
            staffName: a.staffName ?? "",
            color: a.color ?? "#d00000",
            durationMins: 0,
            coStaff: [],
            seq: 0,
          }))
        );
      }

      await Promise.all([loadRoutes(), loadAppointments()]);

      if (!channelRef.current) {
        channelRef.current = supabase
          .channel("map-updates")
          .on("postgres_changes", { event: "*", schema: "public", table: "routes" }, () => loadRoutes())
          .on("postgres_changes", { event: "*", schema: "public", table: "appointments" }, () => loadAppointments())
          .subscribe();
      }
    }

    if (isFree) {
      loadFree();
      if (channelRef.current) {
        supabase.removeChannel(channelRef.current);
        channelRef.current = null;
      }
    } else {
      loadPro();
    }

    return () => {
      if (channelRef.current) {
        supabase.removeChannel(channelRef.current);
        channelRef.current = null;
      }
    };
  }, [isFree]);

  // ── View mode ─────────────────────────────────────────────────────────────
  // "legacy" → scheduledVisits not supplied (live-tracking admin pages): keep
  //   the old always-show-everything behaviour, untouched.
  // "global" → results page, nothing selected: pins only, no routes.
  // "staff"  → results page, a staff member selected: their legs + pins.
  // "visit"  → results page, one appointment selected: 2 legs + 3 pins.
  const isResultsMode = scheduledVisits !== undefined;
  const viewMode: "legacy" | "global" | "staff" | "visit" = !isResultsMode
    ? "legacy"
    : selectedVisitId
    ? "visit"
    : selectedStaffId
    ? "staff"
    : "global";

  const coloredStaffLegs = useMemo(
    () =>
      (staffLegSchedule ?? []).map((l) => ({
        ...l,
        color: LEG_COLORS[l.legIndex % LEG_COLORS.length],
      })),
    [staffLegSchedule]
  );

  const renderLegs = useMemo(() => {
    if (!showRoutes) return [];
    if (viewMode === "legacy") return legs;
    if (viewMode === "global") return [];
    if (viewMode === "visit") {
      // Only the leg arriving at the selected appointment — from wherever
      // the staff member travels from (home/office or the previous visit).
      // The RETURN_TO_BASE_ID sentinel selects the final leg instead, back
      // from the last appointment to home/office.
      if (selectedVisitId === RETURN_TO_BASE_ID) {
        return coloredStaffLegs.filter((l) => l.toVisitId === null);
      }
      return coloredStaffLegs.filter((l) => l.toVisitId === selectedVisitId);
    }
    return coloredStaffLegs; // staff mode
  }, [legs, coloredStaffLegs, viewMode, selectedVisitId, showRoutes]);

  // One pin per unique appointment postcode, with a count badge when more
  // than one appointment shares that location — keeps the no-selection
  // overview readable instead of a wall of overlapping dots/routes.
  const globalLocationGroups = useMemo(() => {
    if (viewMode !== "global" || !scheduledVisits) return [];
    const map = new Map<string, { lat: number; lng: number; visits: ScheduledVisit[] }>();
    for (const v of scheduledVisits) {
      const pc = v.postcode.toUpperCase();
      const geo = geoMapRef.current.get(pc);
      if (!geo) continue;
      if (!map.has(pc)) map.set(pc, { lat: geo.lat, lng: geo.lng, visits: [] });
      map.get(pc)!.visits.push(v);
    }
    return [...map.entries()].map(([postcode, g]) => ({ postcode, ...g }));
  }, [viewMode, scheduledVisits, legs]);

  // Distinct pin for the selected staff member's actual day start/end point.
  // The always-on "Office" pin only ever marks the *global* settings office
  // postcode — but a staff member can have their own office-postcode
  // override, or be set to start from home, in which case their real origin
  // is somewhere else entirely. Without this, the route line would correctly
  // terminate at their real origin while no pin there reflected it. Skipped
  // only when the resolved origin is the same spot as the global office pin
  // (already shown), to avoid drawing two pins on top of each other.
  const originPinGeo = useMemo(() => {
    // Only in staff-overview mode — visit mode already shows a properly
    // labeled/tooltipped bookend pin when the route touches home/office,
    // so this would otherwise draw an exact duplicate on top of it.
    if (viewMode !== "staff") return null;
    if (!selectedStaffId) return null;
    const staffMember = staffList?.find((s) => s.id === selectedStaffId);
    if (!staffMember) return null;
    const originPost = getStaffOriginPostcode(staffMember, officePost).toUpperCase();
    if (!originPost) return null;
    if (originPost === officePost?.toUpperCase()) return null;
    const geo = geoMapRef.current.get(originPost);
    if (!geo) return null;
    const isHome = staffMember.startLocation === "home";
    return {
      ...geo,
      postcode: originPost,
      label: isHome ? "Home" : "Office",
      glyph: isHome ? "H" : "O",
    };
  }, [viewMode, selectedStaffId, staffList, officePost, legs]);

  type BookendStop = {
    key: string;
    lat: number;
    lng: number;
    color: string;
    highlighted?: boolean;
    tooltipLabel?: string;
    marker?: AppointmentMarker;
    plainLabel?: string;
  };

  // For the visit view: only the previous stop ("Start" — home/office or the
  // previous visit) and the selected appointment itself. No departure leg/pin.
  const bookendStops = useMemo<BookendStop[]>(() => {
    if (viewMode !== "visit" || !selectedVisitId) return [];

    const resolveEndpoint = (
      visitId: string | null,
      postcode: string,
      label: string
    ): { lat: number; lng: number; color: string; marker?: AppointmentMarker; plainLabel?: string } => {
      if (visitId) {
        const m = appointments.find((a) => a.id === visitId);
        if (m) return { lat: m.lat, lng: m.lng, color: m.color, marker: m };
      }
      const geo = geoMapRef.current.get(postcode.toUpperCase());
      return {
        lat: geo?.lat ?? 53.0,
        lng: geo?.lng ?? -2.2,
        color: ORIGIN_PIN_COLOR,
        plainLabel: label,
      };
    };

    const isReturn = selectedVisitId === RETURN_TO_BASE_ID;

    const arrivalLeg = isReturn
      ? coloredStaffLegs.find((l) => l.toVisitId === null)
      : coloredStaffLegs.find((l) => l.toVisitId === selectedVisitId);
    if (!arrivalLeg) return [];

    const stops: BookendStop[] = [];

    const prev = resolveEndpoint(arrivalLeg.fromVisitId, arrivalLeg.fromPostcode, arrivalLeg.fromLabel);
    stops.push({
      key: "start",
      ...prev,
      tooltipLabel: `Start${arrivalLeg.departureTime ? " · " + fmtTime(arrivalLeg.departureTime) : ""}`,
    });

    if (isReturn) {
      const end = resolveEndpoint(null, arrivalLeg.toPostcode, arrivalLeg.toLabel);
      stops.push({
        key: "selected",
        ...end,
        highlighted: true,
        tooltipLabel: `End${arrivalLeg.arrivalTime ? " · " + fmtTime(arrivalLeg.arrivalTime) : ""}`,
      });
      return stops;
    }

    const selectedMarker = appointments.find((a) => a.id === selectedVisitId);
    if (!selectedMarker) return [];

    stops.push({
      key: "selected",
      lat: selectedMarker.lat,
      lng: selectedMarker.lng,
      color: selectedMarker.color,
      marker: selectedMarker,
      highlighted: true,
      tooltipLabel: `End${arrivalLeg.arrivalTime ? " · " + fmtTime(arrivalLeg.arrivalTime) : ""}`,
    });

    return stops;
  }, [viewMode, selectedVisitId, coloredStaffLegs, appointments]);

  return (
    <StableMapWrapper>
      {viewMode !== "legacy" && legScheduleLoading && (
        <div className="absolute inset-x-0 top-2 z-[1000] flex justify-center pointer-events-none">
          <span className="rounded-full bg-slate-900/90 px-3 py-1 text-xs text-slate-300 shadow">
            Calculating travel times…
          </span>
        </div>
      )}
      <MapContainer key={mapKey} className={styles.map}>
        <ZoomControl position="topright" />
        <KeepMapSized />
        <MapInitializer zoom={zoom} />
        <FocusManager
          selectedStaffId={selectedStaffId}
          selectedVisitId={selectedVisitId}
          legs={legs}
          markers={appointments}
          officeGeo={officeGeo}
        />

        {/* Route legs — a white casing under each colored line gives clean,
            high-contrast routes that read clearly against the light basemap,
            similar to standard turn-by-turn map apps. */}
        {renderLegs.map((leg) => {
          const isHighlighted = highlightedRouteId === leg.id;
          const weight = isHighlighted ? 7 : 5;
          const travelInfo = "travelMinutes" in leg ? (leg as (typeof coloredStaffLegs)[number]) : null;

          return [
            <Polyline
              key={`${leg.id}-casing`}
              positions={leg.points}
              pathOptions={{
                color: "#ffffff",
                weight: weight + 3,
                opacity: 0.9,
                lineCap: "round",
                lineJoin: "round",
              }}
            />,
            <Polyline
              key={leg.id}
              positions={leg.points}
              eventHandlers={{ click: () => setHighlightedRoute(leg.id) }}
              pathOptions={{
                color: leg.color,
                weight,
                opacity: 1,
                lineCap: "round",
                lineJoin: "round",
              }}
            >
              {travelInfo && (
                <>
                  {/* Label the leg without needing a click. It follows the
                      cursor along the line while hovering, and pins itself
                      open once the leg is selected, so the route you are
                      tracing stays named while you look at the rest. */}
                  <Tooltip
                    // One label carrying everything, shown on hover.
                    //
                    // It was a click-only popup, which meant the lines were
                    // unlabelled until you guessed which to click. Adding a
                    // tooltip as well was worse: your cursor is on the line
                    // when you click it, so both appeared at once, stacked and
                    // repeating the same two names. The popup is gone and this
                    // carries the times instead -- the same detail, without
                    // needing a click or colliding with anything.
                    {...({ sticky: true, direction: "top", opacity: 1 } as any)}
                  >
                    <div style={{ fontSize: 11, lineHeight: 1.6, minWidth: 150 }}>
                      <div>
                        <span style={{ color: "#64748b" }}>Leaving</span>{" "}
                        <strong>{travelInfo.fromLabel}</strong>
                        {travelInfo.departureTime && (
                          <span style={{ color: "#475569" }}>
                            {" "}
                            · {fmtTime(travelInfo.departureTime)}
                          </span>
                        )}
                      </div>
                      <div>
                        <span style={{ color: "#64748b" }}>Arrive at</span>{" "}
                        <strong>{travelInfo.toLabel}</strong>
                        {travelInfo.arrivalTime && (
                          <span style={{ color: "#475569" }}>
                            {" "}
                            · {fmtTime(travelInfo.arrivalTime)}
                          </span>
                        )}
                      </div>
                      <div
                        style={{
                          color: "#475569",
                          marginTop: 3,
                          paddingTop: 3,
                          borderTop: "1px solid #e2e8f0",
                        }}
                      >
                        {travelInfo.travelMinutes != null
                          ? `${travelInfo.travelMinutes} min · ${travelInfo.distanceMiles} mi`
                          : "Calculating…"}
                      </div>
                    </div>
                  </Tooltip>

                </>
              )}
            </Polyline>,
          ];
        })}

        {/* Office pin */}
        {(() => {
          if (!officePost) return null;
          const geo = geoMapRef.current.get(officePost.toUpperCase());
          if (!geo) return null;
          return (
            <Marker
              position={[geo.lat, geo.lng]}
              {...({
                icon: L.divIcon({
                  className: "",
                  html: `<div style="
                    background:#1e293b;
                    width:18px;height:18px;
                    border-radius:3px;
                    border:2px solid white;
                    box-shadow:0 0 6px rgba(0,0,0,0.6);
                    display:flex;align-items:center;justify-content:center;
                    font-size:10px;color:white;font-weight:700;line-height:1;
                  ">O</div>`,
                  iconSize: [18, 18],
                  iconAnchor: [9, 9],
                }),
              } as any)}
            >
              <Popup>
                <div style={{ fontSize: 12, fontWeight: 600 }}>
                  Office — {officePost}
                </div>
              </Popup>
            </Marker>
          );
        })()}

        {/* Distinct pin for the selected staff's real day start/end point,
            when it differs from the global office pin shown above. */}
        {originPinGeo && (
          <Marker
            position={[originPinGeo.lat, originPinGeo.lng]}
            {...({ icon: buildPinIcon({ color: ORIGIN_PIN_COLOR, glyph: originPinGeo.glyph }) } as any)}
          >
            <Popup>
              <div style={{ fontSize: 12, fontWeight: 600 }}>
                {originPinGeo.label} — {originPinGeo.postcode}
              </div>
            </Popup>
          </Marker>
        )}

        {/* Appointment markers — branch by view mode */}
        {showAppointments && viewMode === "legacy" &&
          appointments.map((a) => (
            <Marker
              key={a.id}
              position={[a.lat, a.lng]}
              {...({ icon: buildPinIcon({ color: a.color, highlighted: highlightedAppointmentId === a.id }) } as any)}
              eventHandlers={{ click: () => setHighlightedAppointment(a.id) }}
            >
              <AppointmentPopup a={a} />
            </Marker>
          ))}

        {showAppointments && viewMode === "global" &&
          globalLocationGroups.map((g) => (
            <Marker
              key={g.postcode}
              position={[g.lat, g.lng]}
              {...({
                icon: buildPinIcon({
                  color: GLOBAL_PIN_COLOR,
                  badge: g.visits.length > 1 ? g.visits.length : undefined,
                }),
              } as any)}
            >
              <Popup>
                <div style={{ fontSize: 12, lineHeight: 1.6, minWidth: 160 }}>
                  <div style={{ fontWeight: 700, marginBottom: 3 }}>{g.postcode}</div>
                  {g.visits.map((v) => (
                    <div key={v.id} style={{ color: "#475569" }}>
                      {v.clientName} · {fmtTime(new Date(v.start))}–{fmtTime(new Date(v.end))} · {v.staffName}
                    </div>
                  ))}
                </div>
              </Popup>
            </Marker>
          ))}

        {showAppointments && viewMode === "staff" &&
          appointments
            .filter((a) => a.staffId === selectedStaffId)
            .map((a) => (
              <Marker
                key={a.id}
                position={[a.lat, a.lng]}
                {...({
                  icon: buildPinIcon({
                    color: a.color,
                    badge: a.seq,
                    highlighted: highlightedAppointmentId === a.id,
                  }),
                } as any)}
                eventHandlers={{ click: () => setHighlightedAppointment(a.id) }}
              >
                <AppointmentPopup a={a} />
              </Marker>
            ))}

        {showAppointments && viewMode === "visit" &&
          bookendStops.map((stop) => (
            <Marker
              key={stop.key}
              position={[stop.lat, stop.lng]}
              {...({ icon: buildPinIcon({ color: stop.color, highlighted: stop.highlighted }) } as any)}
            >
              {stop.tooltipLabel && (
                <Tooltip {...({ permanent: true, direction: "top", offset: [0, -28] } as any)}>
                  {stop.tooltipLabel}
                </Tooltip>
              )}
              {stop.marker ? (
                <AppointmentPopup a={stop.marker} />
              ) : (
                <Popup>
                  <div style={{ fontSize: 12, fontWeight: 600 }}>{stop.plainLabel}</div>
                </Popup>
              )}
            </Marker>
          ))}
      </MapContainer>
    </StableMapWrapper>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { supabase } from "@/lib/supabase/client";
import { loadFreeSchedulerData } from "@/lib/freeSession";
import { useUserTier } from "@/lib/hooks/useUserTier";

type RouteSummaryData = {
  total_jobs: number;
  total_distance: number;
  vehicles: number;
};

export default function RouteSummary() {
  const isFree = useUserTier();
  const [summary, setSummary] = useState<RouteSummaryData | null>(null);
  const [loading, setLoading] = useState(true);
  const channelRef = useRef<ReturnType<typeof supabase.channel> | null>(null);

  async function loadFreeSummary(): Promise<RouteSummaryData | null> {
    const data = await loadFreeSchedulerData();
    if (!data) return null;

    const appointments = data.appointments ?? [];
    const routes = data.routes ?? [];

    const total_jobs = appointments.length;
    const vehicles = new Set(routes.map((r: any) => r.staff_id)).size;

    return {
      total_jobs,
      total_distance: 0,
      vehicles,
    };
  }

  async function loadProSummary(): Promise<RouteSummaryData | null> {
    const { data: appointments } = await supabase
      .from("appointments")
      .select("id");

    const { data: routes } = await supabase
      .from("routes")
      .select("staff_id, distance");

    const total_jobs = appointments?.length ?? 0;
    const vehicles = new Set(routes?.map((r: any) => r.staff_id)).size;

    const total_distance = routes?.reduce(
      (sum: number, r: any) => sum + (r.distance ?? 0),
      0
    ) ?? 0;

    return {
      total_jobs,
      total_distance,
      vehicles,
    };
  }

  useEffect(() => {
    async function load() {
      setLoading(true);

      const result = isFree
        ? await loadFreeSummary()
        : await loadProSummary();

      setSummary(result);
      setLoading(false);
    }

    load();

    if (!isFree && !channelRef.current) {
      channelRef.current = supabase
        .channel("route-summary-updates")
        .on(
          "postgres_changes",
          { event: "*", schema: "public", table: "routes" },
          () => load()
        )
        .on(
          "postgres_changes",
          { event: "*", schema: "public", table: "appointments" },
          () => load()
        )
        .subscribe();
    }

    return () => {
      if (channelRef.current) {
        supabase.removeChannel(channelRef.current);
        channelRef.current = null;
      }
    };
  }, [isFree]);

  return (
    <div className="w-full rounded border border-slate-800 bg-slate-950 p-4">
      <h2 className="mb-3 text-sm font-semibold text-slate-100">
        Route Summary
      </h2>

      {loading && (
        <p className="text-xs text-slate-400">Loading summary…</p>
      )}

      {!loading && !summary && (
        <p className="text-xs text-slate-400">No summary available.</p>
      )}

      {!loading && summary && (
        <ul className="space-y-1 text-xs text-slate-200">
          <li>Total Jobs: {summary.total_jobs}</li>
          <li>Total Distance: {summary.total_distance} km</li>
          <li>Vehicles Used: {summary.vehicles}</li>
        </ul>
      )}
    </div>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import { supabase } from "@/lib/supabase/client";
import { useHighlightStore } from "@/lib/map/highlightStore";
import { loadFreeSchedulerData } from "@/lib/freeSession";

type ScheduleTableProps = {
  isFree: boolean;
  showTimes?: boolean;
};

type StaffMember = {
  id: string;
  name: string;
};

type Client = {
  id: string;
  name: string;
};

type AppointmentRow = {
  id: string;
  start_time: string | null;
  end_time: string | null;
  staff: StaffMember[];
  clients: Client[];
};

function hashColor(id: string): string {
  let hash = 0;
  for (let i = 0; i < id.length; i++) {
    hash = (hash << 5) - hash + id.charCodeAt(i);
    hash |= 0;
  }
  const hue = Math.abs(hash) % 360;
  return `hsl(${hue}, 70%, 55%)`;
}

function hasConflict(a: AppointmentRow, b: AppointmentRow): boolean {
  if (!a.start_time || !a.end_time || !b.start_time || !b.end_time) return false;

  const aStart = new Date(a.start_time).getTime();
  const aEnd = new Date(a.end_time).getTime();
  const bStart = new Date(b.start_time).getTime();
  const bEnd = new Date(b.end_time).getTime();

  if (aEnd <= bStart || bEnd <= aStart) return false;

  const aStaffIds = new Set(a.staff.map((s) => s.id));
  return b.staff.some((s) => aStaffIds.has(s.id));
}

export default function ScheduleTable({ isFree, showTimes = true }: ScheduleTableProps) {
  const highlightedAppointmentId = useHighlightStore((s) => s.highlightedAppointmentId);
  const setHighlightedAppointment = useHighlightStore((s) => s.setHighlightedAppointment);

  const [rows, setRows] = useState<AppointmentRow[]>([]);
  const [loading, setLoading] = useState(true);

  async function loadFreeAppointments(): Promise<AppointmentRow[]> {
    const data = await loadFreeSchedulerData();
    const freeAppts = data?.appointments ?? [];

    // Map free-session Appointment objects to AppointmentRow format
    return freeAppts.map((a: any) => ({
      id: a.id ?? crypto.randomUUID(),
      start_time: a.strictStartTime ?? null,
      end_time: null,
      staff: [],
      clients: [{ id: a.id ?? "unknown", name: a.name ?? "Unknown" }],
    }));
  }

  useEffect(() => {
    async function load() {
      setLoading(true);

      if (isFree) {
        const local = await loadFreeAppointments();
        setRows(local);
        setLoading(false);
        return;
      }

      const { data: { user } } = await supabase.auth.getUser();
      if (!user) { setRows([]); setLoading(false); return; }

      const { data, error } = await supabase
        .from("scheduled_visits")
        .select("*")
        .eq("user_id", user.id)
        .order("start_time", { ascending: true });

      if (error) {
        console.error("Error loading schedule:", error);
        setRows([]);
        setLoading(false);
        return;
      }

      const normalized: AppointmentRow[] = (data ?? []).map((row: any) => ({
        id: row.visit_id,
        start_time: row.start_time,
        end_time: row.end_time,
        staff: row.staff_name ? [{ id: row.staff_id, name: row.staff_name }] : [],
        clients: row.client_name ? [{ id: row.appointment_id, name: row.client_name }] : [],
      }));

      setRows(normalized);
      setLoading(false);
    }

    load();

    if (!isFree) {
      const channel = supabase
        .channel("schedule-table-engine")
        .on(
          "postgres_changes",
          { event: "*", schema: "public", table: "scheduled_visits" },
          () => load()
        )
        .subscribe();

      return () => {
        supabase.removeChannel(channel);
      };
    }
  }, [isFree]);

  const conflictIds = useMemo(() => {
    const ids = new Set<string>();
    for (let i = 0; i < rows.length; i++) {
      for (let j = i + 1; j < rows.length; j++) {
        if (hasConflict(rows[i], rows[j])) {
          ids.add(rows[i].id);
          ids.add(rows[j].id);
        }
      }
    }
    return ids;
  }, [rows]);

  if (loading) {
    return (
      <div className="w-full rounded border border-slate-800 bg-slate-950 p-4">
        <p className="text-sm text-slate-300">Loading schedule…</p>
      </div>
    );
  }

  return (
    <div className="w-full rounded border border-slate-800 bg-slate-950 p-4">
      <div className="mb-3 flex items-center justify-between">
        <h2 className="text-sm font-semibold text-slate-100">Schedule</h2>

        <div className="flex items-center gap-2 text-[11px] text-slate-400">
          <span className="inline-flex items-center gap-1">
            <span className="h-2 w-2 rounded-full bg-amber-400" />
            Conflict
          </span>
          <span className="inline-flex items-center gap-1">
            <span className="h-2 w-2 rounded-full bg-sky-400" />
            Highlighted
          </span>
        </div>
      </div>

      <table className="w-full border-collapse text-sm">
        <thead>
          <tr className="border-b border-slate-800">
            <th className="py-2 text-left text-xs font-semibold uppercase tracking-wide text-slate-400">
              Staff
            </th>
            <th className="py-2 text-left text-xs font-semibold uppercase tracking-wide text-slate-400">
              Clients
            </th>
            {showTimes && (
              <th className="py-2 text-left text-xs font-semibold uppercase tracking-wide text-slate-400">
                Start
              </th>
            )}
            {showTimes && (
              <th className="py-2 text-left text-xs font-semibold uppercase tracking-wide text-slate-400">
                End
              </th>
            )}
          </tr>
        </thead>

        <tbody>
          {rows.map((row) => {
            const isHighlighted = highlightedAppointmentId === row.id;
            const isConflict = conflictIds.has(row.id);

            return (
              <tr
                key={row.id}
                className="cursor-pointer border-b border-slate-900"
                onMouseEnter={() => setHighlightedAppointment(row.id)}
                onMouseLeave={() => setHighlightedAppointment(null)}
                style={{
                  backgroundColor: isHighlighted
                    ? "rgba(56,189,248,0.12)"
                    : "transparent",
                  transition: "background-color 120ms ease",
                }}
              >
                <td className="py-2 align-top">
                  {row.staff.length > 0 ? (
                    <div className="flex flex-wrap gap-1">
                      {row.staff.map((s) => (
                        <span
                          key={s.id}
                          className="inline-flex items-center gap-1 rounded-full bg-slate-800 px-2 py-0.5 text-[11px] text-slate-100"
                        >
                          <span
                            className="h-2 w-2 rounded-full"
                            style={{ backgroundColor: hashColor(s.id) }}
                          />
                          {s.name}
                        </span>
                      ))}
                    </div>
                  ) : (
                    <span className="text-slate-500">—</span>
                  )}
                </td>

                <td className="py-2 align-top">
                  {row.clients.length > 0 ? (
                    row.clients.map((c) => c.name).join(", ")
                  ) : (
                    <span className="text-slate-500">—</span>
                  )}
                </td>

                {showTimes && (
                  <td className="py-2 align-top text-slate-200">
                    {row.start_time
                      ? new Date(row.start_time).toLocaleTimeString([], {
                          hour: "2-digit",
                          minute: "2-digit",
                        })
                      : "—"}
                  </td>
                )}

                {showTimes && (
                  <td className="py-2 align-top">
                    <div className="flex items-center gap-2">
                      <span className="text-slate-200">
                        {row.end_time
                          ? new Date(row.end_time).toLocaleTimeString([], {
                              hour: "2-digit",
                              minute: "2-digit",
                            })
                          : "—"}
                      </span>

                      {isConflict && (
                        <span className="rounded-full bg-amber-500/20 px-2 py-0.5 text-[10px] font-semibold text-amber-300">
                          Conflict
                        </span>
                      )}
                    </div>
                  </td>
                )}
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

"use client";

import { useState, useMemo, useEffect } from "react";
import { useStaffStore, Staff, Gender, StartLocation, StaffBreak } from "@/store/staffStore";
import { useSkillsStore, Skill } from "@/store/skillsStore";
import { useSettingsStore } from "@/store/settingsStore";
import PostcodeHint from "@/components/common/PostcodeHint";
import { normalisePostcode } from "@/lib/postcode/validate";

// Shared with the postcode checker so what gets saved is the same string that
// was looked up -- "ls14dy" and "LS1 4DY" must not become two cache entries or
// two different values in the store.
function cleanPostcode(p: string) {
  return normalisePostcode(p);
}

interface AddStaffProps {
  isFree: boolean;
  triggerOnly?: boolean;
}

/** Break row while being edited. Times and length stay as strings so the
 *  inputs can be cleared without collapsing to 0. */
interface BreakFormRow {
  id: string;
  minutes: string;
  windowStart: string;
  windowEnd: string;
}

interface StaffFormState {
  id?: string;
  name: string;
  homePostcode: string;
  officePostcode: string;
  startLocation: StartLocation;
  dateOfBirth: string;
  gender: Gender | "";
  skills: string[];
  workStart: string;
  workEnd: string;
  breaks: BreakFormRow[];
}

/**
 * What the two form components below need.
 *
 * Both took `any`, which meant the form fields -- the largest surface in this
 * component and the one most likely to be edited -- were unchecked: a typo in
 * a field name compiled fine and simply stopped saving that value.
 */
interface StaffFormProps {
  form: StaffFormState;
  setForm: React.Dispatch<React.SetStateAction<StaffFormState>>;
  skills: Skill[];
  handleToggleSkill: (skillId: string) => void;
  handleAddSkillFromInput: (value: string) => void;
  errors: { home?: string; office?: string };
}

interface StaffModalProps extends StaffFormProps {
  isEditing: boolean;
  onClose: () => void;
  onSubmit: () => void;
}

const emptyForm: StaffFormState = {
  name: "",
  homePostcode: "",
  officePostcode: "",
  startLocation: "office",
  dateOfBirth: "",
  gender: "",
  skills: [],
  workStart: "",
  workEnd: "",
  breaks: [],
};

function toBreakRow(b: StaffBreak): BreakFormRow {
  return {
    id: b.id,
    minutes: String(b.minutes),
    windowStart: b.windowStart ?? "",
    windowEnd: b.windowEnd ?? "",
  };
}

function calculateAge(dob: string): number | null {
  if (!dob) return null;
  const birth = new Date(dob);
  if (Number.isNaN(birth.getTime())) return null;
  const today = new Date();
  let age = today.getFullYear() - birth.getFullYear();
  const m = today.getMonth() - birth.getMonth();
  if (m < 0 || (m === 0 && today.getDate() < birth.getDate())) age--;
  return age;
}

export default function AddStaff({ isFree, triggerOnly }: AddStaffProps) {
  const {
    staff,
    addStaff,
    updateStaff,
    deleteStaff,
    selectedStaffIds,
  } = useStaffStore();

  const { skills, addSkill } = useSkillsStore();

  const globalOfficePostcode = useSettingsStore((s) => s.settings.officePostcode);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [form, setForm] = useState<StaffFormState>({
    ...emptyForm,
    officePostcode: globalOfficePostcode,
  });
  const [isEditing, setIsEditing] = useState(false);

  const [errors, setErrors] = useState<{ home?: string; office?: string }>({});

  // Edit mode listener
  useEffect(() => {
    // Dispatched by the staff list to open this modal in edit mode. A
    // CustomEvent rather than a prop because the list and this component have
    // no common parent to hold the state.
    const handler = (e: Event) => {
      const { id } = (e as CustomEvent<{ id: string }>).detail;
      const s = staff.find((x) => x.id === id);
      if (!s) return;

      setIsEditing(true);
      setForm({
        id: s.id,
        name: s.name,
        homePostcode: s.homePostcode,
        officePostcode: s.officePostcode,
        startLocation: s.startLocation ?? "office",
        dateOfBirth: s.dateOfBirth,
        gender: s.gender,
        skills: [...s.skills],
        workStart: s.workStart ?? "",
        workEnd: s.workEnd ?? "",
        breaks: (s.breaks ?? []).map(toBreakRow),
      });
      setErrors({});
      setIsModalOpen(true);
    };

    document.addEventListener("georoute-edit-staff", handler);
    return () => document.removeEventListener("georoute-edit-staff", handler);
  }, [staff]);

  const canAddMore = useMemo(() => {
    if (!isFree) return true;
    return staff.length < 2;
  }, [isFree, staff]);

  const openAddModal = () => {
    setIsEditing(false);
    setForm({ ...emptyForm, officePostcode: globalOfficePostcode });
    setErrors({});
    setIsModalOpen(true);
  };

  const openEditModal = (s: Staff) => {
    setIsEditing(true);
    setForm({
      id: s.id,
      name: s.name,
      homePostcode: s.homePostcode,
      officePostcode: s.officePostcode,
      startLocation: s.startLocation ?? "office",
      dateOfBirth: s.dateOfBirth,
      gender: s.gender,
      skills: [...s.skills],
      workStart: s.workStart ?? "",
      workEnd: s.workEnd ?? "",
      breaks: (s.breaks ?? []).map(toBreakRow),
    });
    setErrors({});
    setIsModalOpen(true);
  };

  const handleSubmit = () => {
    if (!form.name.trim()) return;

    const normalisedHome = cleanPostcode(form.homePostcode);
    const normalisedOffice = form.officePostcode.trim()
      ? cleanPostcode(form.officePostcode)
      : globalOfficePostcode;

    // Rows with no usable length are dropped rather than stored as zero-minute
    // breaks the scheduler would silently ignore.
    const breaksValue: StaffBreak[] = form.breaks
      .map((row) => ({
        id: row.id,
        minutes: parseInt(row.minutes, 10),
        windowStart: row.windowStart || undefined,
        windowEnd: row.windowEnd || undefined,
      }))
      .filter((b) => Number.isFinite(b.minutes) && b.minutes > 0);

    if (isEditing && form.id) {
      updateStaff(form.id, {
        name: form.name.trim(),
        homePostcode: normalisedHome,
        officePostcode: normalisedOffice,
        startLocation: form.startLocation,
        dateOfBirth: form.dateOfBirth,
        gender: form.gender,
        skills: form.skills,
        workStart: form.workStart || undefined,
        workEnd: form.workEnd || undefined,
        breaks: breaksValue,
      });
    } else {
      if (!canAddMore) return;
      addStaff({
        name: form.name.trim(),
        homePostcode: normalisedHome,
        officePostcode: normalisedOffice,
        startLocation: form.startLocation,
        dateOfBirth: form.dateOfBirth,
        gender: form.gender,
        skills: form.skills,
        workStart: form.workStart || undefined,
        workEnd: form.workEnd || undefined,
        breaks: breaksValue,
      });
    }

    setIsModalOpen(false);
  };

  const handleToggleSkill = (skillId: string) => {
    setForm((prev) => {
      const exists = prev.skills.includes(skillId);
      return {
        ...prev,
        skills: exists
          ? prev.skills.filter((id) => id !== skillId)
          : [...prev.skills, skillId],
      };
    });
  };

  const handleAddSkillFromInput = (value: string) => {
    const trimmed = value.trim();
    if (!trimmed) return;
    const skill = addSkill(trimmed);
    setForm((prev) => ({
      ...prev,
      skills: prev.skills.includes(skill.id)
        ? prev.skills
        : [...prev.skills, skill.id],
    }));
  };

  const activeStaff = staff;

  if (triggerOnly) {
    return (
      <>
        <button
          type="button"
          onClick={openAddModal}
          disabled={!canAddMore}
          className="rounded bg-blue-600 px-3 py-1.5 text-sm font-medium text-white disabled:bg-gray-500"
        >
          {canAddMore ? "Add staff" : "Max staff reached"}
        </button>

        {isModalOpen && (
          <StaffModalUI
            isEditing={isEditing}
            form={form}
            setForm={setForm}
            skills={skills}
            handleToggleSkill={handleToggleSkill}
            handleAddSkillFromInput={handleAddSkillFromInput}
            onClose={() => setIsModalOpen(false)}
            onSubmit={handleSubmit}
            errors={errors}
          />
        )}
      </>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h2 className="text-base font-semibold text-slate-200">
          Staff <span className="text-slate-500">(Selected: {selectedStaffIds.length})</span>
        </h2>

        <button
          type="button"
          onClick={openAddModal}
          disabled={!canAddMore}
          className="rounded bg-blue-600 px-3 py-1.5 text-sm font-medium text-white disabled:bg-gray-500"
        >
          {canAddMore ? "Add staff" : "Max staff reached"}
        </button>
      </div>

      {activeStaff.length === 0 && (
        <p className="text-sm text-slate-400">No staff added yet.</p>
      )}

      <ul className="space-y-2">
        {activeStaff.map((s: Staff) => {
          const age = calculateAge(s.dateOfBirth);
          return (
            <li
              key={s.id}
              className="flex items-center justify-between rounded border border-slate-700 bg-slate-900 px-3 py-2 text-sm"
            >
              <span className="font-medium text-slate-100">{s.name}</span>
              <div className="flex items-center gap-2 text-xs text-slate-400">
                {age !== null && <span>{age} yrs</span>}
                {s.gender && <span>{s.gender}</span>}

                <button
                  type="button"
                  onClick={() => openEditModal(s)}
                  className="rounded border border-slate-600 px-2 py-0.5 hover:bg-slate-800"
                >
                  Edit
                </button>

                <button
                  type="button"
                  onClick={() => deleteStaff(s.id)}
                  className="rounded border border-red-600 px-2 py-0.5 text-red-400 hover:bg-red-950"
                >
                  Delete
                </button>
              </div>
            </li>
          );
        })}
      </ul>

      {isModalOpen && (
        <StaffModalUI
          isEditing={isEditing}
          form={form}
          setForm={setForm}
          skills={skills}
          handleToggleSkill={handleToggleSkill}
          handleAddSkillFromInput={handleAddSkillFromInput}
          onClose={() => setIsModalOpen(false)}
          onSubmit={handleSubmit}
          errors={errors}
        />
      )}
    </div>
  );
}

function StaffModalUI({
  isEditing,
  form,
  setForm,
  skills,
  handleToggleSkill,
  handleAddSkillFromInput,
  onClose,
  onSubmit,
  errors,
}: any) {
  return (
    <div className="modal-overlay">
      <div className="modal-container max-w-md">
        <div className="modal-header flex justify-between items-center p-4 border-b border-slate-700">
          <h3 className="text-base font-semibold text-slate-100">
            {isEditing ? "Edit staff" : "Add staff"}
          </h3>
          <button
            onClick={onClose}
            className="text-slate-400 hover:text-white text-xl"
          >
            ×
          </button>
        </div>

        <div className="modal-body p-4 space-y-4 text-sm overflow-y-auto max-h-[70vh]">
          <StaffForm
            form={form}
            setForm={setForm}
            skills={skills}
            handleToggleSkill={handleToggleSkill}
            handleAddSkillFromInput={handleAddSkillFromInput}
            errors={errors}
          />
        </div>

        <div className="modal-footer flex justify-end gap-2 p-4 border-t border-slate-700">
          <button
            type="button"
            onClick={onClose}
            className="rounded border border-slate-600 px-3 py-1.5 text-sm text-slate-300 hover:bg-slate-800"
          >
            Cancel
          </button>

          <button
            type="button"
            onClick={onSubmit}
            className="rounded bg-blue-600 px-3 py-1.5 text-sm font-medium text-white hover:bg-blue-700"
          >
            {isEditing ? "Save" : "Add"}
          </button>
        </div>
      </div>
    </div>
  );
}

function StaffForm({
  form,
  setForm,
  skills,
  handleToggleSkill,
  handleAddSkillFromInput,
  errors,
}: any) {
  return (
    <>
      <div>
        <label className="mb-1 block font-medium text-slate-200">Name</label>
        <input
          type="text"
          value={form.name}
          onChange={(e) => setForm((f) => ({ ...f, name: e.target.value }))}
          className="w-full rounded border border-slate-700 bg-slate-900 px-2 py-1 text-slate-100"
        />
      </div>

      <div>
        <label className="mb-1 block font-medium text-slate-200">Home postcode</label>
        <input
          type="text"
          value={form.homePostcode}
          onChange={(e) =>
            setForm((f) => ({ ...f, homePostcode: e.target.value }))
          }
          className="w-full rounded border border-slate-700 bg-slate-900 px-2 py-1 text-slate-100"
        />
        {errors.home ? (
          <p className="text-xs text-red-400 mt-1">{errors.home}</p>
        ) : (
          // Suppressed while a hard validation error is showing -- two lines of
          // feedback under one field contradict each other more often than they
          // help.
          <PostcodeHint value={form.homePostcode} />
        )}
      </div>

      <div>
        <label className="mb-1 block font-medium text-slate-200">Office postcode</label>
        <input
          type="text"
          value={form.officePostcode}
          onChange={(e) =>
            setForm((f) => ({ ...f, officePostcode: e.target.value }))
          }
          placeholder="Leave blank to use global office postcode"
          className="w-full rounded border border-slate-700 bg-slate-900 px-2 py-1 text-slate-100"
        />
        {errors.office ? (
          <p className="text-xs text-red-400 mt-1">{errors.office}</p>
        ) : (
          <PostcodeHint value={form.officePostcode} />
        )}
      </div>

      <div>
        <label className="mb-1 block font-medium text-slate-200">Starts day from</label>
        <div className="flex items-center gap-4">
          <label className="flex items-center gap-1.5 text-slate-300">
            <input
              type="radio"
              name="startLocation"
              checked={form.startLocation === "home"}
              onChange={() => setForm((f) => ({ ...f, startLocation: "home" }))}
            />
            Home
          </label>
          <label className="flex items-center gap-1.5 text-slate-300">
            <input
              type="radio"
              name="startLocation"
              checked={form.startLocation !== "home"}
              onChange={() => setForm((f) => ({ ...f, startLocation: "office" }))}
            />
            Office
          </label>
        </div>
        <p className="mt-1 text-xs text-slate-400">
          Used to work out their first/last travel leg of the day.
        </p>
      </div>

      <div>
        <label className="mb-1 block font-medium text-slate-200">Date of birth</label>
        <input
          type="date"
          value={form.dateOfBirth}
          onChange={(e) =>
            setForm((f) => ({ ...f, dateOfBirth: e.target.value }))
          }
          className="w-full rounded border border-slate-700 bg-slate-900 px-2 py-1 text-slate-100"
        />
      </div>

      <div>
        <label className="mb-1 block font-medium text-slate-200">Gender</label>
        <select
          value={form.gender}
          onChange={(e) =>
            setForm((f) => ({
              ...f,
              gender: e.target.value as Gender | "",
            }))
          }
          className="w-full rounded border border-slate-700 bg-slate-900 px-2 py-1 text-slate-100"
        >
          <option value="">Select gender</option>
          <option value="Male">Male</option>
          <option value="Female">Female</option>
          <option value="Other">Other</option>
        </select>
      </div>

      <div>
        <label className="mb-1 block font-medium text-slate-200">Working hours</label>
        <p className="mb-2 text-xs text-slate-400">Leave blank to use the global day start/end from settings.</p>
        <div className="flex items-center gap-2">
          <input
            type="time"
            value={form.workStart}
            onChange={(e) => setForm((f) => ({ ...f, workStart: e.target.value }))}
            className="flex-1 rounded border border-slate-700 bg-slate-900 px-2 py-1 text-slate-100"
          />
          <span className="text-slate-400">to</span>
          <input
            type="time"
            value={form.workEnd}
            onChange={(e) => setForm((f) => ({ ...f, workEnd: e.target.value }))}
            className="flex-1 rounded border border-slate-700 bg-slate-900 px-2 py-1 text-slate-100"
          />
        </div>
      </div>

      <div>
        <label className="mb-1 block font-medium text-slate-200">Breaks</label>
        <p className="mb-2 text-xs text-slate-400">
          Unpaid breaks such as lunch. Nothing is scheduled during them. Leave
          the window blank to let a break fall anywhere in the working day.
        </p>

        <div className="space-y-2">
          {form.breaks.map((row: BreakFormRow, i: number) => {
            const update = (patch: Partial<BreakFormRow>) =>
              setForm((f) => ({
                ...f,
                breaks: f.breaks.map((r: BreakFormRow) =>
                  r.id === row.id ? { ...r, ...patch } : r
                ),
              }));

            return (
              <div
                key={row.id}
                className="rounded border border-slate-700 bg-slate-900/60 px-2 py-2"
              >
                <div className="flex items-center gap-2">
                  <input
                    type="number"
                    min={5}
                    step={5}
                    aria-label={`Break ${i + 1} length in minutes`}
                    placeholder="30"
                    value={row.minutes}
                    onChange={(e) => update({ minutes: e.target.value })}
                    className="w-20 rounded border border-slate-700 bg-slate-900 px-2 py-1 text-slate-100"
                  />
                  <span className="text-xs text-slate-400">min, between</span>
                  <input
                    type="time"
                    aria-label={`Break ${i + 1} earliest start`}
                    value={row.windowStart}
                    onChange={(e) => update({ windowStart: e.target.value })}
                    className="flex-1 rounded border border-slate-700 bg-slate-900 px-2 py-1 text-slate-100"
                  />
                  <span className="text-xs text-slate-400">and</span>
                  <input
                    type="time"
                    aria-label={`Break ${i + 1} latest end`}
                    value={row.windowEnd}
                    onChange={(e) => update({ windowEnd: e.target.value })}
                    className="flex-1 rounded border border-slate-700 bg-slate-900 px-2 py-1 text-slate-100"
                  />
                  <button
                    type="button"
                    aria-label={`Remove break ${i + 1}`}
                    onClick={() =>
                      setForm((f) => ({
                        ...f,
                        breaks: f.breaks.filter((r: BreakFormRow) => r.id !== row.id),
                      }))
                    }
                    className="rounded border border-slate-700 px-2 py-1 text-xs text-slate-400 hover:border-red-500/60 hover:text-red-300"
                  >
                    ✕
                  </button>
                </div>
              </div>
            );
          })}
        </div>

        <button
          type="button"
          onClick={() =>
            setForm((f) => ({
              ...f,
              breaks: [
                ...f.breaks,
                { id: crypto.randomUUID(), minutes: "30", windowStart: "", windowEnd: "" },
              ],
            }))
          }
          className="mt-2 rounded border border-slate-700 px-3 py-1 text-xs text-slate-200 hover:bg-slate-800"
        >
          + Add break
        </button>
      </div>

      <div>
        <label className="mb-1 block font-medium text-slate-200">Skills</label>

        <div className="mb-2 flex flex-wrap gap-2">
          {skills.map((skill: Skill) => {
            const active = form.skills.includes(skill.id);
            return (
              <button
                key={skill.id}
                type="button"
                onClick={() => handleToggleSkill(skill.id)}
                className={`rounded border px-2 py-0.5 text-xs ${
                  active
                    ? "border-blue-500 bg-blue-900 text-blue-300"
                    : "border-slate-600 text-slate-300 hover:bg-slate-800"
                }`}
              >
                {skill.name}
              </button>
            );
          })}
        </div>

        <input
          type="text"
          placeholder="Type a skill and press Enter"
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.preventDefault();
              const target = e.target as HTMLInputElement;
              handleAddSkillFromInput(target.value);
              target.value = "";
            }
          }}
          className="w-full rounded border border-slate-700 bg-slate-900 px-2 py-1 text-sm text-slate-100"
        />
      </div>
    </>
  );
}

"use client";

import { useState } from "react";
import {
  useCustomWindowStore,
  CustomWindow,
} from "@/store/customWindowStore";

interface CustomWindowsManagerProps {
  isFree: boolean;
}

interface WindowFormState {
  id?: string;
  name: string;
  start: string;
  end: string;
  minGapToNext: string;
}

const emptyForm: WindowFormState = {
  name: "",
  start: "08:00",
  end: "10:00",
  minGapToNext: "0",
};

export default function CustomWindowsManager({ isFree }: CustomWindowsManagerProps) {
  const { windows, addWindow, updateWindow, deleteWindow } =
    useCustomWindowStore();

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [form, setForm] = useState<WindowFormState>(emptyForm);

  const openAddModal = () => {
    setIsEditing(false);
    setForm(emptyForm);
    setIsModalOpen(true);
  };

  const openEditModal = (w: CustomWindow) => {
    setIsEditing(true);
    setForm({
      id: w.id,
      name: w.name,
      start: w.start,
      end: w.end,
      minGapToNext: String(w.minGapToNext),
    });
    setIsModalOpen(true);
  };

  const handleSubmit = () => {
    if (!form.name.trim()) return;

    const minGap = Math.max(0, parseInt(form.minGapToNext || "0", 10));

    const payload = {
      name: form.name.trim(),
      start: form.start,
      end: form.end,
      minGapToNext: minGap,
    };

    if (isEditing && form.id) {
      updateWindow(form.id, payload);
    } else {
      addWindow(payload);
    }

    setIsModalOpen(false);
    setForm(emptyForm);
  };

  return (
    <div className="space-y-3 rounded border border-slate-800 bg-slate-950 p-3 text-sm">
      <div className="flex items-center justify-between">
        <h3 className="text-sm font-semibold text-slate-200">Custom Time Windows</h3>
        <button
          type="button"
          onClick={openAddModal}
          className="rounded bg-blue-600 px-2 py-1 text-xs font-medium text-white hover:bg-blue-700"
        >
          Add window
        </button>
      </div>

      {windows.length === 0 && (
        <p className="text-xs text-slate-400">No windows yet. Add Breakfast, Lunch, etc.</p>
      )}

      <ul className="space-y-1 text-xs">
        {windows.map((w: CustomWindow) => (
          <li
            key={w.id}
            className="flex items-center justify-between rounded border border-slate-800 px-2 py-1"
          >
            <div className="flex flex-col">
              <span className="font-medium text-slate-200">{w.name}</span>
              <span className="text-slate-400">
                {w.start} – {w.end}
              </span>
              {w.minGapToNext > 0 && (
                <span className="text-slate-500">
                  Min gap to next: {w.minGapToNext} mins
                </span>
              )}
            </div>

            <div className="flex items-center gap-2">
